CARDIO.register({"item":"d162","meta":{"num":"d162","label":"162","spe":"dermato","short":"IST, syphilis, HPV","title":"Infections sexuellement transmissibles (IST)","section":"D","chapter":9,"pages":"177-208","sdd":[{"num":16,"label":"Adénopathies uniques ou multiples"},{"num":80,"label":"Alopécie et chute de cheveux"},{"num":91,"label":"Anomalie des muqueuses"},{"num":101,"label":"Écoulement urétral"},{"num":104,"label":"Leucorrhées"},{"num":235,"label":"Démarche diagnostique et dépistage rapide du VIH"},{"num":305,"label":"Dépistage et conseils devant une infection sexuellement transmissible"},{"num":310,"label":"Prévention chez un malade contagieux"},{"num":322,"label":"Vaccinations de l'adulte et de l'enfant"}]},"objectives":[{"id":"d162-obj-01","rank":"A","rubric":"Étiologies","title":"Connaître les causes des IST selon leur expression clinique","desc":""},{"id":"d162-obj-02","rank":"B","rubric":"Prévalence, épidémiologie","title":"Connaître la fréquence des différentes IST et leurs facteurs de risque","desc":""},{"id":"d162-obj-03","rank":"A","rubric":"Prise en charge","title":"Connaître les mesures préventives des IST","desc":"Préservatif, vaccination"},{"id":"d162-obj-04","rank":"A","rubric":"Prise en charge","title":"Connaître les principes de prise en charge du ou des partenaires","desc":""},{"id":"d162-obj-05","rank":"A","rubric":"Étiologies","title":"Connaître les causes des ulcérations génitales infectieuses ou non infectieuses","desc":""},{"id":"d162-obj-06","rank":"A","rubric":"Contenu multimédia","title":"Herpès génital","desc":""},{"id":"d162-obj-07","rank":"A","rubric":"Contenu multimédia","title":"Syphilis primaire (chancre)","desc":""},{"id":"d162-obj-08","rank":"A","rubric":"Diagnostic positif","title":"Connaître les signes cliniques de l'urétrite masculine","desc":"Prostatite, orchiépididymite"},{"id":"d162-obj-09","rank":"B","rubric":"Étiologies","title":"Connaître les causes des urétrites chez l'homme","desc":""},{"id":"d162-obj-10","rank":"A","rubric":"Diagnostic positif","title":"Connaître les signes cliniques d'une infection génitale basse chez la femme","desc":""},{"id":"d162-obj-11","rank":"B","rubric":"Diagnostic positif","title":"Connaître les signes cliniques d'une infection génitale haute chez la femme (salpingite, endométrite)","desc":""},{"id":"d162-obj-12","rank":"A","rubric":"Étiologies","title":"Connaître les causes d'infections génitales basses chez la femme","desc":""},{"id":"d162-obj-13","rank":"B","rubric":"Étiologies","title":"Connaître les causes d'infections génitales hautes chez la femme","desc":""},{"id":"d162-obj-14","rank":"B","rubric":"Diagnostic positif","title":"Connaître les manifestations extragénitales des IST","desc":""},{"id":"d162-obj-15","rank":"A","rubric":"Examens complémentaires","title":"Connaître les examens complémentaires à réaliser en cas d'IST : ulcérations génitales, urétrites, orchites, infections basses de la femme, infections hautes de la femme, localisations extragénitales","desc":""},{"id":"d162-obj-16","rank":"B","rubric":"Prise en charge","title":"Connaître les mesures générales de prise en charge des IST (médicamenteux et non médicamenteux)","desc":""},{"id":"d162-obj-17","rank":"B","rubric":"Examens complémentaires","title":"Connaître les explorations à réaliser en cas d'infection génitale haute chez la femme","desc":""},{"id":"d162-obj-18","rank":"A","rubric":"Prise en charge","title":"Connaître les modalités du traitement probabiliste des IST","desc":""},{"id":"d162-obj-19","rank":"A","rubric":"Prise en charge","title":"Connaître les modalités de dépistage des infections à HPV","desc":"Prévention"},{"id":"d162-obj-20","rank":"A","rubric":"Prise en charge","title":"Savoir choisir les antibiotiques après documentation microbiologique de l'IST","desc":""},{"id":"d162-obj-21","rank":"B","rubric":"Prise en charge","title":"Connaître les modalités thérapeutiques des infections génitales hautes de la femme","desc":""},{"id":"d162-obj-22","rank":"A","rubric":"Prise en charge","title":"Connaître les modalités de prévention des IST","desc":"Prévention (vaccination comprise)"},{"id":"d162-obj-23","rank":"A","rubric":"Diagnostic positif","title":"Connaître les signes cliniques d'une syphilis précoce","desc":""},{"id":"d162-obj-24","rank":"B","rubric":"Diagnostic positif","title":"Connaître les signes cliniques d'une syphilis tardive","desc":""},{"id":"d162-obj-25","rank":"B","rubric":"Diagnostic positif","title":"Connaître les différentes présentations cliniques de la syphilis secondaire (formes neurologiques notamment)","desc":""},{"id":"d162-obj-26","rank":"B","rubric":"Contenu multimédia","title":"Photographie d'une éruption au stade de syphilis secondaire","desc":""},{"id":"d162-obj-27","rank":"A","rubric":"Examens complémentaires","title":"Connaître les tests sérologiques au cours de la syphilis","desc":""},{"id":"d162-obj-28","rank":"A","rubric":"Prise en charge","title":"Savoir traiter la syphilis primaire","desc":""},{"id":"d162-obj-29","rank":"B","rubric":"Prise en charge","title":"Savoir traiter la syphilis secondaire","desc":""},{"id":"d162-obj-30","rank":"A","rubric":"Diagnostic positif","title":"Connaître les manifestations cliniques liées au HPV","desc":""},{"id":"d162-obj-31","rank":"B","rubric":"Prise en charge","title":"Connaître les modalités de traitement des infections liées au HPV","desc":""},{"id":"d162-obj-32","rank":"B","rubric":"Étiologies","title":"Connaître les étiologies parasitaires des IST","desc":"Trichomonose, phtiriase"},{"id":"d162-obj-33","rank":"B","rubric":"Diagnostic positif","title":"Connaître les examens complémentaires à réaliser pour le diagnostic d'une trichomonose, d'une infection à Chlamydia trachomatis et Neisseria gonorrhoeae","desc":"Prélèvement à acheminer rapidement au laboratoire si examen direct"},{"id":"d162-obj-34","rank":"B","rubric":"Prise en charge","title":"Connaître les modalités du traitement d'une trichomonose, d'une infection à Chlamydia trachomatis et Neisseria gonorrhoeae","desc":"Molécules, patient et partenaire(s) simultanément"},{"id":"d162-obj-35","rank":"A","rubric":"Suivi et/ou pronostic","title":"Principales conséquences à long terme des infections génitales hautes chez la femme","desc":""},{"id":"d162-obj-36","rank":"B","rubric":"Diagnostic positif","title":"Reconnaître les particularités des IST en fonction de l'âge","desc":"Étiologies chez la femme ménopausée et chez la jeune fille"},{"id":"d162-obj-37","rank":"B","rubric":"Contenu multimédia","title":"Photographie de condylomes","desc":""}],"course":{"sections":[{"id":"d162-sec-01","title":"Situer les IST : partir du signe d'appel","rank":"A","objectives":["d162-obj-01","d162-obj-02","d162-obj-05","d162-obj-06","d162-obj-09","d162-obj-12"],"content":"**IST** = infection sexuellement transmissible. Démarche : partir du **signe d'appel**, puis chercher le germe.\n\n| Signe d'appel | Causes à évoquer |\n|---|---|\n| **Écoulement urétral** (urétrite, homme) | **gonocoque**, **Chlamydia trachomatis** ; trichomonose [B] |\n| **Leucorrhées** (pertes vaginales), **cervicite** (femme) | mêmes germes ; **Trichomonas** [B] |\n| **Ulcération génitale, anale ou buccale** | **syphilis**, herpès, chancre mou, donovanose, lymphogranulomatose vénérienne (LGV) |\n| **Éruption, adénopathies, alopécie** | **syphilis secondaire** |\n| **Végétations** (« crêtes-de-coq ») | **HPV** (papillomavirus humain) : condylomes |\n\n**Ulcération génitale : comparer au chancre syphilitique** (indolore, fond propre, induré, adénopathie non inflammatoire)\n- **Herpès** : ulcérations superficielles **douloureuses**, contours polycycliques.\n- **Chancre mou** : fond sale, **très douloureux**, adénopathies inflammatoires ; sujets africains.\n- **Donovanose** : peu douloureuse, aspect granulomateux ; sujets africains.\n- **LGV** (ou maladie de Nicolas-Favre) : anorectite, ulcérations anogénitales, diarrhée trompeuse ; sujets africains ou homosexuels masculins.\n\n- Candidose et vaginose bactérienne : **pas** des IST ; la trichomonose en est une.\n- Autres IST, vues dans d'autres items : herpès (item 168), VIH (virus de l'immunodéficience humaine, item 169), hépatites, phtiriase et scabiose (item 171) [B].\n- [B] Épidémiologie : HPV = IST la plus fréquente ; Chlamydia = 1re cause identifiée d'urétrite aiguë ; syphilis en hausse depuis 2000, surtout chez les homosexuels masculins.","keyPoints":["Ulcération génitale, anale ou buccale : penser **d'abord à la syphilis** ; autres causes : herpès, chancre mou, donovanose, LGV.","Herpès = ulcérations **douloureuses** à contours polycycliques ; chancre syphilitique = **indolore**, induré.","Écoulement urétral ou cervicite : **gonocoque** et **Chlamydia trachomatis**.","Trichomonose = IST ; candidose et vaginose bactérienne = **pas** des IST.","Toute IST : chercher une **IST associée** et traiter les **partenaires**."],"pitfalls":["Urétrite **mixte** possible (gonocoque + Chlamydia dans 15 % des cas) : on traite toujours aussi le Chlamydia.","Aucun caractère du chancre n'est pathognomonique : toute ulcération muqueuse aiguë doit faire évoquer la syphilis."],"src":"p. 177-179, 187, 189, 196-197, 200, 206, 208"},{"id":"d162-sec-02","title":"Gonococcie : urétrite et cervicite à gonocoque","rank":"A","objectives":["d162-obj-08","d162-obj-10","d162-obj-12","d162-obj-14","d162-obj-15","d162-obj-18","d162-obj-20","d162-obj-33","d162-obj-34"],"content":"**Germe** : *Neisseria gonorrhoeae* (gonocoque), **diplocoque à Gram négatif**. **Incubation courte : 2 à 7 jours** ; le patient est contagieux.\n\n**Reconnaître**\n- **Homme** : urétrite antérieure aiguë **bruyante** (portage asymptomatique exceptionnel) : écoulement **purulent** (90 %), dysurie (gêne à la miction), brûlures, prurit urétral.\n- **Femme** : **asymptomatique dans 70 % des cas** ; sinon cervicite : leucorrhées purulentes, pesanteur pelvienne, signes d'urétrite, col peu inflammatoire avec pus à l'orifice. Si l'infection monte (endométrite, salpingite) : douleurs pelviennes, stérilité tubaire, grossesse extra-utérine (GEU), moins souvent qu'avec Chlamydia.\n- **Pharynx, anus** : le plus souvent **asymptomatiques** (anorectite muette dans 2/3 des cas). Portage pharyngé fréquent chez les homo- ou bisexuels : le **rechercher** si rapports à risque (oro-génitaux réceptifs non protégés). Les antibiotiques y diffusent mal → portage persistant après traitement.\n- [B] Complications : prostatite, épididymite (homme) ; **septicémie** (fièvre, lésions cutanées, arthrites).\n\n**Examens**\n- **PCR** (amplification génique), couplée à celle de Chlamydia (**PCR biplex**) : **1er jet d'urine** chez l'homme (10-20 mL, ≥ 2 h après la dernière miction), **auto-écouvillonnage vaginal** chez la femme ; gorge et/ou anus selon les pratiques. Patient symptomatique : prélever l'écoulement urétral s'il existe.\n- [B] **Culture** systématique : confirme et donne l'**antibiogramme** (la PCR n'en donne pas). Examen direct : diplocoques intracellulaires « en grains de café ».\n\n**Traiter** : traitement « minute » = dose unique (DU) donnée en consultation.\n- **Ceftriaxone 1 g IM** (intramusculaire, pour le gonocoque) **+ anti-Chlamydia systématique** (urétrite mixte dans 15 %) : **doxycycline 7 jours**, préférée à l'azithromycine 1 g.\n- Rapports évités ou protégés **≥ 7 jours** ; **partenaires traités** ; même schéma si VIH.\n- [B] Résistances croissantes du gonocoque (pénicilline, cyclines, ciprofloxacine) : schémas à réactualiser. Contrôle clinique à J7 (7e jour) ; si forme asymptomatique, PCR de contrôle à 15 jours.","keyPoints":["Gonocoque : incubation **courte (2-7 j)**, écoulement urétral **purulent** (90 %).","Femme : **70 % asymptomatiques** ; sinon cervicite avec leucorrhées purulentes.","Diagnostic : **PCR** sur 1er jet d'urine (homme) ou auto-écouvillonnage vaginal (femme) ; gorge et anus selon les pratiques.","Traitement minute : **ceftriaxone + anti-Chlamydia systématique** (doxycycline 7 j).","**Partenaires traités**, rapports évités ou protégés **≥ 7 jours**."],"pitfalls":["Pharynx et anus : souvent muets mais contagieux ; les prélever en cas de pratiques à risque.","La PCR ne donne pas la sensibilité aux antibiotiques : la culture garde un intérêt [B]."],"src":"p. 179-183, 187"},{"id":"d162-sec-03","title":"Chlamydiose : Chlamydia trachomatis et conséquences tardives","rank":"A","objectives":["d162-obj-08","d162-obj-10","d162-obj-11","d162-obj-12","d162-obj-13","d162-obj-14","d162-obj-15","d162-obj-20","d162-obj-21","d162-obj-33","d162-obj-34","d162-obj-35"],"content":"**Germe** : *Chlamydia trachomatis*, bacille à Gram négatif **intracellulaire obligatoire** (sérotypes D à K : infections urogénitales ; L1-L3 : lymphogranulomatose vénérienne [B]).\n\n**Pourquoi c'est un enjeu** : **portage asymptomatique très fréquent** (**50 % chez l'homme, 50 à 90 % chez la femme**) → la bactérie circule sans bruit et les complications tardives surviennent.\n\n**Reconnaître** : tableau **moins bruyant** que le gonocoque ; incubation variable (jours à mois).\n- **Homme** : urétrite ; écoulement présent dans < 50 % des cas, **clair, modéré, intermittent**.\n- **Femme** : cervicite le plus souvent asymptomatique ; sinon leucorrhées blanchâtres ou jaunâtres, cystalgies (douleurs vésicales), dyspareunie (douleur aux rapports) ; col fragile, sécrétions mucopurulentes.\n- Pharynx, anus : rarement symptomatiques.\n\n**Conséquences à long terme chez la femme** (infection génitale haute, IGH : endométrite, salpingite, souvent subaiguës ou chroniques) : **douleurs pelviennes inflammatoires, stérilité tubaire, grossesse extra-utérine (GEU)**. Chlamydia = 50 % des salpingites de la femme jeune, **70 % des stérilités tubaires**.\n- [B] Homme : épididymite, prostatite chronique. Deux sexes : syndrome oculo-urétro-synovial (arthrite réactionnelle, urétrite, conjonctivite). Nouveau-né : conjonctivite, pneumopathie.\n\n**Examens** : **PCR = examen clé** (plus sensible que la culture) : 1er jet d'urine (homme) ; auto-écouvillonnage vaginal (femme symptomatique) ou vulvovaginal (asymptomatique). **Sérologie inutile.**\n\n**Traiter** : **doxycycline 100 mg 2 fois/jour pendant 7 jours** (azithromycine 1 g en dose unique si observance incertaine) ; partenaires traités.\n- [B] **Femme enceinte** : azithromycine 1 g en dose unique (cyclines contre-indiquées) ; PCR de contrôle à 1 mois.\n- [B] IGH non compliquée : ceftriaxone 1 g (dose unique) + doxycycline + métronidazole 10 jours ; PCR de contrôle à 2-3 mois.","keyPoints":["Chlamydia : **portage asymptomatique** très fréquent (50 % des hommes, 50-90 % des femmes).","Écoulement urétral **clair, intermittent**, présent dans moins de 50 % des cas.","Diagnostic : **PCR** (examen clé) ; la **sérologie est inutile**.","Chez la femme, conséquences tardives : douleurs pelviennes, **stérilité tubaire**, **GEU**.","Traitement : **doxycycline 7 jours** ; partenaires traités."],"pitfalls":["Pas de symptôme ne veut pas dire pas d'infection : le portage silencieux entretient la transmission et les complications.","PCR de contrôle trop précoce (avant 4 semaines) : faux positif possible [B].","Femme enceinte : la doxycycline (une cycline) est contre-indiquée, on utilise l'azithromycine [B]."],"src":"p. 182-187"},{"id":"d162-sec-04","title":"Syphilis : définition, chancre et syphilis secondaire","rank":"A","objectives":["d162-obj-05","d162-obj-07","d162-obj-23","d162-obj-24","d162-obj-25","d162-obj-26"],"content":"**Syphilis** : IST due à *Treponema pallidum* (spirochète), **très contagieuse** et **non immunisante** (on peut se réinfecter). Transmission essentiellement sexuelle, fellation comprise [B].\n- **Précoce** (< 1 an) = primaire + secondaire + **latente précoce** (sérologie positive, aucun signe, début < 1 an). **Tardive** (> 1 an) = tertiaire + latente tardive.\n\n**Syphilis primaire** : incubation 10-90 jours (**3 semaines** en moyenne) → **chancre** + **adénopathie satellite**.\n- **Chancre** : érosion de 5-15 mm, en général **unique** (parfois multiple « en miroir »), **fond propre**, **indurée** (impossible à plisser entre 2 doigts : le caractère le plus évocateur), **indolore**. Il fourmille de tréponèmes : **contagieux**.\n- Sièges : sillon balano-préputial (homme), vulve (femme), bouche, pharynx, anus. Chancre du vagin, du col, du rectum ou du pharynx : **invisible**, diagnostic souvent manqué.\n- **Adénopathie** satellite **non inflammatoire**, souvent unilatérale.\n- **Guérison spontanée** en quelques semaines sans séquelle, mais la maladie continue : ~30 % des patients non traités font une syphilis secondaire ; une forme tardive est possible sans passer par elle.\n- Aucun caractère n'est pathognomonique → **toute ulcération muqueuse aiguë** (génitale, orale, anale) : penser syphilis.\n\n**Syphilis secondaire** (diffusion du tréponème, en règle < 1 an) : éruptions successives (« floraisons »), polymorphes, + signes généraux ; « **grande simulatrice** ».\n- **Roséole** : macules rose pâle du tronc, dans les 6 semaines après le chancre, disparaît en 7-10 jours → ne pas la confondre avec une **virose** (dont la primo-infection VIH) ou une **toxidermie**.\n- **Syphilides** (lésions cutanées) **papuleuses** : papules **cuivrées**, fine desquamation possible ; **papules palmo-plantaires** (~30 %) : **très évocatrices** ; syphilides génitales très contagieuses.\n- [B] Peut simuler une dermatite séborrhéique, une acné, un psoriasis, un lichen plan, un eczéma.\n- [B] Atteinte oculaire ou d'une paire crânienne = neurosyphilis précoce → ponction lombaire.","keyPoints":["Chancre : **indolore, indurée, à fond propre**, avec adénopathie **non inflammatoire** ; incubation moyenne **3 semaines**.","Toute **ulcération muqueuse aiguë** (génitale, orale, anale) : évoquer la syphilis.","Précoce < 1 an (primaire, secondaire, latente précoce) ; tardive > 1 an.","Syphilis secondaire = « **grande simulatrice** » : papules **cuivrées**, papules **palmo-plantaires** très évocatrices.","Roséole : ne pas la confondre avec une **virose** ou une **toxidermie**."],"pitfalls":["Chancre invisible (vagin, col, rectum, pharynx) : syphilis primaire souvent méconnue.","Le chancre guérit seul : la disparition de la lésion ne veut pas dire que la syphilis est guérie."],"src":"p. 187-193, 196-197, 200"},{"id":"d162-sec-05","title":"Syphilis : lire la sérologie","rank":"A","objectives":["d162-obj-15","d162-obj-27"],"content":"Le tréponème **ne se cultive pas** : le diagnostic repose surtout sur la **sérologie** (2 familles de tests).\n\n| Test | Exemples | À retenir |\n|---|---|---|\n| **TT** (test tréponémique) | **ELISA** (test immuno-enzymatique automatisé), TPHA (test d'agglutination) | **spécifique** des tréponématoses ; qualitatif |\n| **TNT** (test non tréponémique) | **VDRL** (Venereal Disease Research Laboratory), **RPR** (Rapid Plasma Reagin) | **non spécifique** ; **titre** = évolutivité, suivi |\n\n- **Ordre** : **ELISA en 1er** ; **TNT seulement si le TT est positif**.\n- **Cinétique** : TT positif dès le 7e-10e jour du chancre, TNT vers le 10e-15e jour → pendant les **7 premiers jours du chancre, TT et TNT peuvent être négatifs**.\n- **Syphilis secondaire** : TT **et** TNT **toujours positifs** (titre du TNT en général entre 1/16 et 1/128). Syphilis primaire : tous les profils sont possibles.\n\n**Lire le résultat** (TT d'abord, puis TNT)\n\n| TT | TNT | Interprétation |\n|---|---|---|\n| − | − | pas de tréponématose (ou chancre de moins de 7 jours) |\n| + | + | tréponématose ; titre élevé (ex. 1/16) = maladie **évolutive** |\n| + | − | **cicatrice sérologique** (guérie) ou infection très précoce |\n| − | + | le plus souvent **fausse sérologie** : **lupus**, **syndrome des anticorps anti-phospholipides (SAPL)**, **grossesse** |\n\n- Aucun test ne distingue la syphilis des tréponématoses non vénériennes (pian, béjel, pinta).\n- Suivi du traitement : **TNT quantitatif** (le TT quantitatif varie trop d'un examen à l'autre).","keyPoints":["**ELISA (TT) en premier** ; **TNT seulement si TT positif**.","Syphilis secondaire : **TT et TNT toujours positifs**.","**7 premiers jours du chancre** : TT et TNT possiblement négatifs.","TNT positif isolé (TT négatif) = **fausse sérologie** (lupus, SAPL, grossesse) ; TT + et TNT − = **cicatrice sérologique**.","Le TT dit s'il y a une tréponématose ; le TNT renseigne l'évolutivité et sert au suivi."],"pitfalls":["Sérologie négative dans les 7 premiers jours d'un chancre : elle n'élimine pas la syphilis.","TNT positif isolé : le plus souvent faux positif, mais il peut précéder le TT (10 % des cas) en début de syphilis primaire."],"src":"p. 194-196, 200"},{"id":"d162-sec-06","title":"Syphilis : traiter, suivre, partenaires","rank":"A","objectives":["d162-obj-04","d162-obj-18","d162-obj-20","d162-obj-28","d162-obj-29"],"content":"**Règle de l'OMS** (Organisation mondiale de la santé) : devant une **ulcération génitale**, **ne pas attendre** les résultats de la sérologie (TT, test tréponémique ; TNT, test non tréponémique) pour traiter. Si syphilis précoce suspectée : examen clinique soigneux (signes neurologiques, oculaires), **rechercher une autre IST** (gonocoque, Chlamydia, VIH, hépatite B), prescrire un TT ; avis spécialisé dans les cas délicats (femme enceinte, patient séropositif pour le VIH, allergie à la pénicilline).\n\n**Traitement des syphilis précoces** (primaire, secondaire, latente précoce : **même schéma**)\n- **Benzathine-benzylpénicilline 2,4 MU** (millions d'unités) **IM, 1 seule injection**.\n- **Allergie** à la pénicilline : **doxycycline 100 mg matin et soir pendant 14 jours**, sauf femme enceinte et patient séropositif pour le VIH (pour eux : induction de tolérance à la pénicilline).\n- **Réaction d'Herxheimer** : quelques heures après l'injection (surtout en secondaire), liée à la **lyse des tréponèmes** → fièvre, céphalées, myalgies, éruption accentuée. **Bénigne, ce n'est pas une allergie** ; antipyrétique ; prévenir le patient.\n\n**Suivi** : clinique + **TNT quantitatif** à **3 mois, 6 mois, 1 an**, puis chaque année jusqu'à négativation.\n- Efficace si le titre est **divisé par 4 à 6 mois** ; sinon avis spécialisé et **3 injections** de benzathine-benzylpénicilline 2,4 MU à 8 jours d'intervalle.\n- **Titre multiplié par 4** = **recontamination**. TNT négatif attendu 1 an après une syphilis primaire, 2 ans après une secondaire.\n\n**Partenaires** d'une syphilis certaine : contact **< 6 semaines** → **traiter d'emblée** (2,4 MU) + sérologie ; contact **> 6 semaines** → **sérologie** : positive → traiter, négative → refaire à **3 mois**.\n- Patient séropositif pour le VIH : même traitement ; sérologie syphilis au moins 1 fois par an si pratiques à risque.\n- Syphilis **grave chez la femme enceinte** (atteinte fœtale après le 4e mois).\n- Avoir une syphilis = sexualité à haut risque : chercher d'autres IST, répéter la prévention.","keyPoints":["Ulcération génitale : **ne pas attendre** la sérologie pour traiter (OMS).","Syphilis précoce : **benzathine-benzylpénicilline 2,4 MU IM, 1 injection** ; allergie : **doxycycline 14 jours**.","**Herxheimer** = fièvre, céphalées, myalgies après l'injection : **bénin, pas une allergie**.","Suivi : **TNT quantitatif** à 3 mois, 6 mois, 1 an puis annuel ; titre **÷ 4 à 6 mois** ; **× 4** = recontamination.","Contact : **< 6 semaines → traiter**, **> 6 semaines → sérologie** (refaite à 3 mois si négative)."],"pitfalls":["Ne pas prendre une réaction d'Herxheimer pour une allergie à la pénicilline.","Doxycycline : pas chez la femme enceinte ni chez le patient séropositif pour le VIH."],"src":"p. 197-200"},{"id":"d162-sec-07","title":"HPV : reconnaître les condylomes et examiner","rank":"A","objectives":["d162-obj-02","d162-obj-15","d162-obj-19","d162-obj-30","d162-obj-37"],"content":"**HPV** (papillomavirus humain) : une des IST les **plus fréquentes** (formes latentes), surtout chez les 16-25 ans ; la plupart des sujets éliminent le virus en quelques mois.\n- [B] **Bas risque** (HPV 6 et 11) : ~90 % des **condylomes** (verrues génitales). **Haut risque**, oncogènes (**HPV 16 et 18**) : lésions précancéreuses puis cancers.\n- [B] Transmission surtout sexuelle ; aussi par linge humide ou à l'accouchement. VIH et immunodépression : plus fréquent, plus sévère.\n\n**Reconnaître** : le diagnostic des **condylomes est clinique**, par un examen complet anal et génital.\n- **Condylomes acuminés** (« **crêtes-de-coq** ») : masses charnues hérissées de verrucosités de 0,2 à 1 cm, de quelques-unes à plusieurs dizaines.\n- **Condylomes plans** : maculo-papules rosées, parfois invisibles à l'œil nu → **acide acétique** pour les révéler.\n- **Néoplasies intra-épithéliales** : lésions précancéreuses (col, vulve, anus, pénis), risque de carcinome épidermoïde surtout au col.\n- Sièges : homme = pubis, prépuce, sillon balano-préputial ; femme = vulve, souvent **multifocal** (vagin, périnée, anus) → examen gynécologique et anal complet.\n- Enfant : contamination manuportée (verrues) ou par linge, ou mère-enfant ; **mauvais marqueur de sévices sexuels**.\n\n**Examens**\n- Col : **frottis cervico-vaginal** ± colposcopie (acide acétique à 5 %), ou **test HPV-HR** (haut risque, par PCR, amplification génique) **à partir de 30 ans** : avant 30 ans le virus n'est pas encore éliminé, le test est presque toujours positif sans maladie.\n- Anus : anuscopie. **Biopsie** seulement si doute ou suspicion de néoplasie.\n- Chercher une **IST associée (25 %)** : VIH, test tréponémique, hépatite B ; PCR Chlamydia et gonocoque.\n- [B] Différentiels : couronne perlée du gland, syphilides secondaires, kératoses séborrhéiques, molluscum contagiosum, nodules scabieux.","keyPoints":["Condylomes : diagnostic **clinique** (« crêtes-de-coq »).","[B] HPV 6 et 11 : condylomes ; **HPV 16 et 18** : lésions précancéreuses et cancers.","Toujours chercher une **IST associée** (25 %) ; chez la femme, examen gynécologique et dépistage du col.","Col : **frottis** ou **test HPV-HR à partir de 30 ans**.","Enfant : condylomes = **mauvais marqueur de sévices sexuels**."],"pitfalls":["Test HPV-HR avant 30 ans : presque toujours positif sans maladie, il est réservé aux femmes de 30 ans et plus.","Condylomes plans : parfois invisibles à l'œil nu, d'où l'acide acétique."],"src":"p. 200-203, 205-206"},{"id":"d162-sec-08","title":"HPV : traiter, vacciner, dépister","rank":"A","objectives":["d162-obj-03","d162-obj-19","d162-obj-22","d162-obj-31"],"content":"**Traitement des condylomes** [B] : il n'existe **pas de traitement du virus** ; on **détruit les lésions visibles**. Récidives fréquentes (le virus persiste dans la peau saine) → suivi à 1 mois, puis tous les 3 mois jusqu'à guérison, puis à 6 mois.\n- Destruction **physique** (cryothérapie à l'azote liquide, laser CO2, électrocoagulation : risque cicatriciel), **chimique** (podophyllotoxine 0,5 %, appliquée par le patient, **contre-indiquée pendant la grossesse**) ou **immunologique** (imiquimod).\n- Informer : dédramatiser (un comportement à risque n'est pas nécessaire pour avoir des condylomes) et **examiner le/la partenaire**.\n\n**Prévenir par la vaccination** : protège contre les dysplasies du col, de l'anus et de l'oropharynx ; surtout efficace **avant toute contamination**.\n\n| Population | Schéma (vaccin **nonavalent**, 9 types d'HPV) |\n|---|---|\n| Filles **et garçons** de **11 à 14 ans** | **2 doses** (espacées de 6 à 13 mois) |\n| Rattrapage de **15 à 19 ans** révolus | **3 doses** (0, 2 et 6 mois) |\n| **HSH** (hommes ayant des rapports sexuels avec des hommes) | **3 doses** jusqu'à **26 ans** révolus |\n\n- Immunodéprimés : mêmes âges, rattrapage jusqu'à 19 ans. Toute nouvelle vaccination commence par le vaccin nonavalent.\n\n**Dépister le cancer du col** : **frottis cervico-vaginal tous les 3 ans** ou **test HPV-HR** (haut risque) ; dysplasie même mineure → **colposcopie** (± biopsie dirigée). Vaccin + dépistage = prévention du cancer du col.","keyPoints":["**Vaccin nonavalent** : filles **et garçons** de 11-14 ans (**2 doses**), rattrapage 15-19 ans (**3 doses**, 0-2-6 mois).","**HSH** : vaccination jusqu'à **26 ans** (3 doses).","La vaccination est préventive : à faire **avant toute contamination**.","Prévention du cancer du col = **vaccin + dépistage** (frottis tous les 3 ans ou test HPV-HR).","[B] Pas de traitement du virus : on détruit les lésions ; **récidives fréquentes**."],"pitfalls":["Podophyllotoxine : contre-indiquée chez la femme enceinte [B].","Les condylomes n'impliquent pas un comportement à risque : dédramatiser, ne pas culpabiliser [B]."],"src":"p. 204-206"},{"id":"d162-sec-09","title":"Trichomonose et autres IST","rank":"B","objectives":["d162-obj-32","d162-obj-33","d162-obj-34"],"content":"**Trichomonose** : due à *Trichomonas vaginalis*, **protozoaire flagellé**. C'est une **IST**, contrairement à la candidose et à la vaginose bactérienne. Transmission presque exclusivement sexuelle ; incubation de 4 à 28 jours.\n\n**Reconnaître**\n- **Homme** : le plus souvent **asymptomatique** ; sinon urétrite subaiguë ou balanoposthite (gland et prépuce), parfois écoulement matinal et prurit.\n- **Femme** : asymptomatique dans la majorité des cas ; sinon vulvovaginite ou cervicovaginite : **prurit intense**, leucorrhées **abondantes, verdâtres, spumeuses, malodorantes**, vulve œdématiée, **colpite « léopard »** (aspect ponctué du col au spéculum).\n- Différencier d'une vaginose bactérienne et d'une candidose : pas toujours aisé.\n\n**Diagnostic** : **examen direct à l'état frais** (le parasite est **mobile**) ou **PCR**. Prélèvement : écoulement urétral ou 1er jet d'urine (homme) ; cul-de-sac vaginal postérieur (femme).\n\n**Traiter** : **métronidazole** (2 g en dose unique, ou 500 mg 2 fois/jour pendant 7 jours) ou secnidazole 2 g en dose unique. **Traiter simultanément le/la partenaire** (forte transmissibilité).\n- Proposer au patient et à ses partenaires : VIH, test tréponémique, hépatite B, PCR Chlamydia + gonocoque.\n\n**Autres IST**, vues dans d'autres items : herpès (168), VIH (169), hépatites, phtiriase et scabiose (171) ; la scabiose se transmet comme une IST → chercher des conduites à risque et dépister les autres IST.","keyPoints":["Trichomonose = IST (protozoaire) ; **asymptomatique** le plus souvent.","Femme : leucorrhées **verdâtres, spumeuses, malodorantes**, prurit, colpite « léopard ».","Diagnostic : examen direct à l'état frais (parasite **mobile**) ou PCR.","Traitement : **métronidazole** (ou secnidazole) + **partenaire traité en même temps**."],"pitfalls":["Ne pas confondre avec la vaginose bactérienne ou la candidose, qui ne sont pas des IST."],"src":"p. 206-208"},{"id":"d162-sec-10","title":"Conduite commune à toute IST : partenaires, dépistage, prévention","rank":"A","objectives":["d162-obj-02","d162-obj-03","d162-obj-04","d162-obj-16","d162-obj-18","d162-obj-20","d162-obj-22","d162-obj-35"],"content":"**Devant toute IST**\n- **Partenaires** : identifier les partenaires contaminés ou contaminateurs et leur proposer dépistage, diagnostic ou **traitement probabiliste** (sans attendre les résultats).\n- **Autres IST** : proposer **systématiquement** une sérologie **VIH**, un **test tréponémique** (TT, syphilis) et une sérologie **hépatite B** ; PCR Chlamydia + gonocoque selon le cas.\n- **Pas de rapports non protégés** pendant le traitement (≥ 7 jours pour une urétrite) ; insister sur le risque de **recontamination** ; éduquer le patient.\n- **PrEP** (prophylaxie pré-exposition au VIH, traitement préventif) à envisager si prises de risque trop régulières.\n\n**Traitement probabiliste** (urétrite et contacts) : traitement « minute » en consultation. Préférer **ceftriaxone + doxycycline 7 jours** : l'azithromycine en dose unique est remise en question (résistances apparues chez un autre germe, Mycoplasma genitalium). Même traitement si VIH.\n\n**Après documentation du germe**, adapter l'antibiotique : gonocoque → ceftriaxone ; Chlamydia → doxycycline ; syphilis → benzathine-benzylpénicilline ; trichomonose → métronidazole.\n\n**Prévenir** : **préservatif** et **vaccination anti-HPV** ; dépistage des partenaires et des sujets à risque.\n- [B] Dépistage : Chlamydia par autoprélèvement vaginal chez les femmes de moins de 25 ans ; sérologie de la syphilis chez les sujets à risque (au moins 1 fois par an si VIH), obligatoire au 1er trimestre de grossesse.\n- **Conséquences tardives d'une infection génitale haute (IGH) chez la femme** : douleurs pelviennes inflammatoires, stérilité tubaire, grossesse extra-utérine (GEU) → enjeu de santé publique chez les sujets jeunes.","keyPoints":["Devant toute IST : **partenaires**, proposer **VIH + test tréponémique + hépatite B**, rapports protégés, **PrEP** si risques répétés.","Traitement probabiliste de l'urétrite : **ceftriaxone + doxycycline 7 jours**.","Prévention : **préservatif** + **vaccination anti-HPV**.","Conséquences tardives d'une IGH chez la femme : douleurs pelviennes, **stérilité tubaire**, **GEU**."],"pitfalls":["Traiter un patient sans traiter ses partenaires expose à la recontamination.","Azithromycine 1 g en dose unique : commode, mais la doxycycline 7 jours est préférée."],"src":"p. 182, 185, 187-188, 205, 208"}],"essentials":[{"id":"d162-ess-01","rank":"A","text":"Caractères du chancre syphilitique : ulcération **indolore**, à fond propre, **indurée** (impossible à plisser), avec adénopathie satellite **non inflammatoire**.","src":"p. 188-190"},{"id":"d162-ess-02","rank":"A","text":"Devant une ulcération muqueuse aiguë (génitale, orale ou anale) : évoquer systématiquement la **syphilis**, car aucun caractère du chancre n'est pathognomonique.","src":"p. 189"},{"id":"d162-ess-03","rank":"A","text":"Ordre des tests de sérologie syphilitique : **ELISA** (test tréponémique, TT) en premier ; **TNT** (test non tréponémique : VDRL ou RPR) seulement si le TT est positif.","src":"p. 194, 200"},{"id":"d162-ess-04","rank":"A","text":"Sérologie au début du chancre : durant les **7 premiers jours**, le test tréponémique (TT) et le non tréponémique (TNT) peuvent être **négatifs** → traiter sans attendre (recommandation de l'OMS, Organisation mondiale de la santé).","src":"p. 195-197"},{"id":"d162-ess-05","rank":"A","text":"Sérologie de la syphilis secondaire : le test tréponémique (TT) et le non tréponémique (TNT) sont **toujours positifs** (titre du TNT généralement entre 1/16 et 1/128).","src":"p. 195, 200"},{"id":"d162-ess-06","rank":"A","text":"Sérologie de syphilis discordante : TNT (test non tréponémique) positif avec TT (test tréponémique) négatif = **fausse sérologie** (lupus, syndrome des anticorps anti-phospholipides, grossesse) ; TT positif avec TNT négatif = **cicatrice sérologique**.","src":"p. 194-196"},{"id":"d162-ess-07","rank":"A","text":"Traitement de la syphilis précoce : **benzathine-benzylpénicilline 2,4 MU** (millions d'unités) en **une injection IM** (intramusculaire) ; si allergie, **doxycycline 14 jours**.","src":"p. 198"},{"id":"d162-ess-08","rank":"A","text":"Réaction d'Herxheimer après l'injection : fièvre, céphalées, myalgies quelques heures après, liée à la lyse des tréponèmes ; **bénigne**, ce n'est **pas** une allergie à la pénicilline.","src":"p. 198"},{"id":"d162-ess-09","rank":"A","text":"Suivi biologique d'une syphilis traitée : **TNT quantitatif** (test non tréponémique) ; titre **divisé par 4** à 6 mois ; titre **multiplié par 4** = recontamination.","src":"p. 195, 198"},{"id":"d162-ess-10","rank":"A","text":"Contact sexuel d'une syphilis certaine : **< 6 semaines** → traiter d'emblée (une injection de 2,4 millions d'unités, MU) ; **> 6 semaines** → sérologie, à refaire à 3 mois si négative.","src":"p. 198"},{"id":"d162-ess-11","rank":"A","text":"Syphilis secondaire, lésions évocatrices : papules **cuivrées** et papules **palmo-plantaires** ; la roséole ne doit pas être confondue avec une virose ou une toxidermie.","src":"p. 191-192, 200"},{"id":"d162-ess-12","rank":"A","text":"Classification de la syphilis : **précoce** (< 1 an) = primaire, secondaire, latente précoce ; **tardive** (> 1 an) = tertiaire, latente tardive.","src":"p. 188"},{"id":"d162-ess-13","rank":"A","text":"Gonococcie de l'homme : incubation courte de **2 à 7 jours** et écoulement urétral **purulent** dans 90 % des cas.","src":"p. 180"},{"id":"d162-ess-14","rank":"A","text":"Gonococcie de la femme : asymptomatique dans **70 %** des cas ; sinon cervicite avec leucorrhées purulentes et col peu inflammatoire.","src":"p. 180-181"},{"id":"d162-ess-15","rank":"A","text":"Gonocoque et Chlamydia, diagnostic : **PCR** (amplification génique) sur **1er jet d'urine** chez l'homme, **auto-écouvillonnage vaginal** chez la femme.","src":"p. 181, 185"},{"id":"d162-ess-16","rank":"A","text":"Traitement minute d'une urétrite : **ceftriaxone** en dose unique + **anti-Chlamydia systématique** (**doxycycline 7 jours** préférée à l'azithromycine 1 g) ; rapports protégés **≥ 7 jours** et partenaires traités.","src":"p. 182, 187"},{"id":"d162-ess-17","rank":"A","text":"Chlamydia trachomatis, clinique : portage **asymptomatique** très fréquent (50 % des hommes, 50 à 90 % des femmes) ; écoulement urétral **clair**, intermittent.","src":"p. 184"},{"id":"d162-ess-18","rank":"A","text":"Chlamydia trachomatis, examen clé : **PCR** ; la **sérologie** n'a aucun intérêt pour le diagnostic.","src":"p. 185"},{"id":"d162-ess-19","rank":"A","text":"Conséquences à long terme d'une infection génitale haute chez la femme : douleurs pelviennes inflammatoires, **stérilité tubaire**, **grossesse extra-utérine**.","src":"p. 181, 183-184"},{"id":"d162-ess-20","rank":"A","text":"Conduite à tenir devant toute IST (infection sexuellement transmissible) : traiter les **partenaires**, proposer **VIH + test tréponémique + hépatite B**, pas de rapports non protégés pendant le traitement, **PrEP** (prophylaxie pré-exposition au VIH) si prises de risque répétées.","src":"p. 182, 185, 208"},{"id":"d162-ess-21","rank":"A","text":"Diagnostic et bilan des condylomes : examen **clinique** (« crêtes-de-coq ») et recherche d'une **IST associée** (25 % des cas).","src":"p. 201, 205"},{"id":"d162-ess-22","rank":"A","text":"Dépistage du cancer du col de l'utérus : **frottis tous les 3 ans** ou **test HPV-HR** (haut risque, à partir de 30 ans) ; dysplasie même mineure → colposcopie.","src":"p. 202, 205"},{"id":"d162-ess-23","rank":"A","text":"Vaccin anti-HPV nonavalent : filles **et garçons** de **11 à 14 ans** (2 doses), rattrapage **15-19 ans** (3 doses, 0-2-6 mois), HSH (hommes ayant des rapports sexuels avec des hommes) jusqu'à **26 ans**.","src":"p. 204-205"},{"id":"d162-ess-24","rank":"B","text":"Types d'HPV et conséquences : HPV **6 et 11** (bas risque) = ~90 % des condylomes ; HPV **16 et 18** (haut risque) = lésions précancéreuses puis cancers.","src":"p. 201"},{"id":"d162-ess-25","rank":"B","text":"Trichomonose, signes, diagnostic et traitement : leucorrhées **verdâtres, spumeuses, malodorantes**, parasite **mobile** à l'examen direct ; **métronidazole** et partenaire traité en même temps.","src":"p. 207-208"}],"numbers":[{"id":"d162-num-01","rank":"A","label":"Incubation de la gonococcie","value":"2 à 7 jours (courte)","src":"p. 180"},{"id":"d162-num-02","rank":"A","label":"Gonococcie masculine : fréquence de l'écoulement purulent","value":"90 % des cas","src":"p. 180"},{"id":"d162-num-03","rank":"A","label":"Gonococcie chez la femme : part des formes asymptomatiques","value":"70 %","src":"p. 180"},{"id":"d162-num-04","rank":"A","label":"Urétrite mixte (gonocoque + Chlamydia)","value":"15 % des cas → traitement anti-Chlamydia systématique","src":"p. 182"},{"id":"d162-num-05","rank":"A","label":"Chlamydia trachomatis : portage asymptomatique","value":"50 % chez l'homme ; 50 à 90 % chez la femme","src":"p. 184"},{"id":"d162-num-06","rank":"A","label":"Part des stérilités tubaires dues à Chlamydia trachomatis","value":"70 % (et 50 % des salpingites de la femme jeune)","src":"p. 183"},{"id":"d162-num-07","rank":"A","label":"Rapports sexuels après traitement d'une urétrite","value":"évités ou protégés pendant au moins 7 jours","src":"p. 182"},{"id":"d162-num-08","rank":"A","label":"Syphilis primaire : durée d'incubation","value":"10 à 90 jours, 3 semaines en moyenne","src":"p. 188"},{"id":"d162-num-09","rank":"A","label":"Syphilis précoce / tardive : limite de durée","value":"précoce < 1 an ; tardive > 1 an","src":"p. 188"},{"id":"d162-num-10","rank":"A","label":"Chancres non traités évoluant vers une syphilis secondaire","value":"environ 30 %","src":"p. 190"},{"id":"d162-num-11","rank":"A","label":"Début du chancre : période où la sérologie (TT, TNT) peut être négative","value":"les 7 premiers jours","src":"p. 195-196"},{"id":"d162-num-12","rank":"A","label":"Syphilis précoce : traitement de référence","value":"benzathine-benzylpénicilline 2,4 MU (millions d'unités) en 1 injection IM (intramusculaire)","src":"p. 198"},{"id":"d162-num-13","rank":"A","label":"Syphilis précoce avec allergie à la pénicilline","value":"doxycycline 100 mg matin et soir pendant 14 jours (sauf femme enceinte et VIH)","src":"p. 198"},{"id":"d162-num-14","rank":"A","label":"Efficacité du traitement de la syphilis : évolution du titre du TNT (test non tréponémique)","value":"divisé par 4 à 6 mois ; multiplié par 4 = recontamination","src":"p. 195, 198"},{"id":"d162-num-15","rank":"A","label":"Contrôles d'une syphilis traitée","value":"3 mois, 6 mois, 1 an, puis chaque année jusqu'à négativation","src":"p. 198"},{"id":"d162-num-16","rank":"A","label":"Contact sexuel d'une syphilis certaine : seuil de 6 semaines","value":"< 6 semaines : traiter ; > 6 semaines : sérologie (refaite à 3 mois si négative)","src":"p. 198"},{"id":"d162-num-17","rank":"A","label":"Condylomes : fréquence d'une IST associée","value":"25 % des cas en moyenne","src":"p. 205"},{"id":"d162-num-18","rank":"A","label":"Dépistage du col : test HPV-HR (haut risque) ou frottis","value":"test HPV-HR à partir de 30 ans ; frottis tous les 3 ans","src":"p. 202, 205"},{"id":"d162-num-19","rank":"A","label":"Vaccin HPV nonavalent : schémas","value":"11-14 ans : 2 doses ; 15-19 ans : 3 doses (0-2-6 mois) ; HSH (hommes ayant des rapports sexuels avec des hommes) jusqu'à 26 ans : 3 doses","src":"p. 204-205"},{"id":"d162-num-20","rank":"B","label":"Trichomonose : incubation et traitement minute","value":"4 à 28 jours ; métronidazole 2 g en dose unique","src":"p. 207"}],"mnemonics":[{"id":"d162-mn-01","rank":"A","title":"Caractères du chancre syphilitique","mnemonic":"PINS","expansion":"- **P**ropre : fond propre, rosé\n- **I**ndolore\n- i**N**duré : impossible à plisser entre 2 doigts (le caractère le plus évocateur)\n- **S**atellite : adénopathie non inflammatoire\n\nÀ côté : 5-15 mm, en général unique.","src":"p. 188-190"},{"id":"d162-mn-02","rank":"A","title":"Sérologie de la syphilis : qui fait quoi ?","mnemonic":"Le TT tranche, le TNT titre","expansion":"- **TT** (ELISA, TPHA) : **tranche** → affirme ou infirme une tréponématose (qualitatif)\n- **TNT** (VDRL, RPR) : **titre** → précise l'évolutivité et sert au suivi (÷ 4 à 6 mois)\n- Ordre : ELISA d'abord ; TNT seulement si le TT est positif.","src":"p. 194-195, 200"},{"id":"d162-mn-03","rank":"A","title":"Ulcération génitale : les 5 causes à comparer","mnemonic":"Sept Hérissons Chantent Devant Nicolas (S-H-C-D-N)","expansion":"- **S**yphilis : indolore, indurée, fond propre\n- **H**erpès : douloureuse, contours polycycliques\n- **C**hancre mou : fond sale, très douloureux, adénopathies inflammatoires\n- **D**onovanose : peu douloureuse, granulomateuse\n- **N**icolas-Favre (LGV) : anorectite, ulcérations anogénitales, diarrhée trompeuse","src":"p. 188, 197"},{"id":"d162-mn-04","rank":"A","title":"Sérologies à proposer systématiquement devant une IST","mnemonic":"V.T.H.","expansion":"- **V** : VIH\n- **T** : test tréponémique (syphilis)\n- **H** : hépatite B\n\nÀ proposer à chaque IST, en plus du traitement des partenaires.","src":"p. 182, 185, 208"},{"id":"d162-mn-05","rank":"A","title":"Gonocoque ou Chlamydia ?","mnemonic":"G = Gros bruit, C = Calme","expansion":"- **G**onocoque = **G**ros bruit : incubation courte (2-7 j), écoulement purulent (90 %), femme asymptomatique dans 70 %\n- **C**hlamydia = **C**alme : portage asymptomatique 50 % (hommes) et 50-90 % (femmes), écoulement clair dans moins de 50 %, incubation variable","src":"p. 180, 184, 186"},{"id":"d162-mn-06","rank":"A","title":"Vaccin anti-HPV : combien de doses ?","mnemonic":"2 pour les jeunes, 3 pour les grands","expansion":"- **11-14 ans** (filles et garçons) : **2 doses** (espacées de 6 à 13 mois)\n- **15-19 ans** (rattrapage) : **3 doses** (0, 2, 6 mois)\n- **HSH jusqu'à 26 ans** : **3 doses** (0, 2, 6 mois)\n\nVaccin nonavalent (9 types d'HPV).","src":"p. 204-205"}]},"questions":[{"id":"d162-qroc-001","type":"QROC","rank":"A","objective":"d162-obj-01","tags":["étiologie"],"difficulty":1,"question":"Quels sont les deux principaux germes responsables d'urétrite (et, chez la femme, de cervicite) ?","answer":"Chlamydia trachomatis et le gonocoque (Neisseria gonorrhoeae)","accept":["chlamydia et gonocoque","gonocoque et chlamydia","chlamydia trachomatis et gonocoque","gonocoque et chlamydia trachomatis","neisseria gonorrhoeae et chlamydia trachomatis"],"keywords":["chlamydia","gonoc"],"explanation":"Chlamydia trachomatis et le gonocoque dominent les urétrites. Leurs équivalents féminins (cervicites, cervicovaginites) ont la même épidémiologie et la même prise en charge.","src":"p. 187"},{"id":"d162-qroc-002","type":"QROC","rank":"A","objective":"d162-obj-01","tags":["étiologie","définition"],"difficulty":1,"question":"Quel est l'aspect du gonocoque (Neisseria gonorrhoeae) à la coloration de Gram ?","answer":"Diplocoque à Gram négatif (encapsulé), intra- ou extracellulaire","accept":["diplocoque à gram négatif","diplocoque gram négatif","diplocoque gram -","diplocoques à gram négatif","diplocoques gram négatif"],"keywords":["diplocoque","gram"],"explanation":"Le gonocoque est un diplocoque encapsulé à Gram négatif, que l'on voit à l'intérieur ou à l'extérieur des cellules.","src":"p. 179"},{"id":"d162-qroc-003","type":"QROC","rank":"A","objective":"d162-obj-08","tags":["clinique"],"difficulty":1,"question":"Quelle est la durée d'incubation, courte, d'une gonococcie ?","answer":"2 à 7 jours","accept":["2 à 7 jours","2-7 jours","entre 2 et 7 jours","2 à 7 j"],"keywords":["2","7"],"explanation":"L'incubation de la gonococcie est courte (2 à 7 jours) et le malade est contagieux. Celle de la chlamydiose est plus longue et variable (de quelques jours à quelques mois).","src":"p. 180, 184"},{"id":"d162-qroc-004","type":"QROC","rank":"A","objective":"d162-obj-08","tags":["clinique"],"difficulty":1,"question":"Quel signe est présent dans environ 90 % des urétrites gonococciques de l'homme ?","answer":"Un écoulement urétral purulent","accept":["écoulement purulent","écoulement urétral purulent","ecoulement uretral purulent","urétrite purulente"],"keywords":["purulent"],"explanation":"L'urétrite antérieure aiguë est la manifestation la plus fréquente : écoulement purulent (90 %), dysurie, brûlures urétrales. Dans la chlamydiose, l'écoulement est au contraire clair, modéré et inconstant.","src":"p. 180, 184"},{"id":"d162-qroc-005","type":"QROC","rank":"A","objective":"d162-obj-10","tags":["clinique","pièges"],"difficulty":1,"question":"Quelle proportion des infections gonococciques non compliquées de la femme est asymptomatique ?","answer":"70 %","accept":["70 %","70%","70 pour cent","environ 70 %"],"keywords":["70"],"explanation":"L'infection gonococcique de la femme est asymptomatique dans 70 % des cas. Quand elle s'exprime, c'est surtout par une cervicite avec leucorrhées purulentes.","src":"p. 180"},{"id":"d162-qroc-006","type":"QROC","rank":"A","objective":"d162-obj-10","tags":["clinique"],"difficulty":2,"question":"À l'examen au spéculum d'une cervicite gonococcique, quel est l'aspect du col ?","answer":"Col non ou peu inflammatoire, avec un écoulement purulent à l'orifice cervical","accept":["col peu inflammatoire","col non inflammatoire","col non ou peu inflammatoire","peu inflammatoire"],"keywords":["inflammatoire","purulent"],"explanation":"La cervicite gonococcique associe leucorrhées purulentes, pesanteur pelvienne et parfois signes d'urétrite, avec un col peu inflammatoire mais un écoulement purulent à l'orifice cervical.","src":"p. 180-181"},{"id":"d162-qroc-007","type":"QROC","rank":"A","objective":"d162-obj-15","tags":["paraclinique","diagnostic"],"difficulty":1,"question":"Dans un contexte de dépistage du gonocoque, quelle technique est préconisée, le plus souvent couplée à la recherche de C. trachomatis ?","answer":"La PCR (amplification génique), souvent biplex avec C. trachomatis","accept":["pcr","pcr biplex","amplification génique","amplification genique"],"keywords":["pcr"],"explanation":"En dépistage, on utilise une PCR, le plus souvent biplex (gonocoque et C. trachomatis). Elle ne permet pas de tester la sensibilité de la souche, d'où l'intérêt de la culture quand on veut un antibiogramme.","src":"p. 181-182"},{"id":"d162-qroc-008","type":"QROC","rank":"A","objective":"d162-obj-15","tags":["paraclinique"],"difficulty":1,"question":"Chez l'homme, sur quel prélèvement réalise-t-on la PCR gonocoque / C. trachomatis ?","answer":"1er jet urinaire (10 à 20 mL), au moins 2 h après la dernière miction","accept":["1er jet urinaire","premier jet urinaire","1er jet d'urine","premier jet d'urine","jet urinaire"],"keywords":["jet"],"explanation":"Chez l'homme, la PCR se fait sur un 1er jet urinaire de 10 à 20 mL, au moins 2 heures après la dernière miction. En cas d'écoulement urétral spontané, on peut aussi le prélever.","src":"p. 181, 185"},{"id":"d162-qroc-009","type":"QROC","rank":"A","objective":"d162-obj-15","tags":["paraclinique"],"difficulty":1,"question":"Chez la femme, quel prélèvement est recommandé pour la PCR gonocoque / C. trachomatis ?","answer":"Un auto-écouvillonnage vaginal","accept":["auto-écouvillonnage vaginal","autoprélèvement vaginal","auto prélèvement vaginal","écouvillonnage vaginal","prélèvement vaginal"],"keywords":["vaginal"],"explanation":"Chez la femme, on privilégie l'auto-écouvillonnage vaginal, y compris chez la femme symptomatique (plutôt que l'écouvillonnage de l'endocol par un professionnel). Selon les pratiques sexuelles, on ajoute des prélèvements pharyngé et/ou anal.","src":"p. 181, 185"},{"id":"d162-qroc-010","type":"QROC","rank":"A","objective":"d162-obj-18","tags":["traitement"],"difficulty":1,"question":"Quel traitement doit être systématiquement associé à celui d'une gonococcie, car l'urétrite est mixte dans 15 % des cas ?","answer":"Un traitement anti-Chlamydia","accept":["anti-chlamydia","anti chlamydia","traitement anti-chlamydia","traitement de la chlamydiose","traitement chlamydia"],"keywords":["chlamydia"],"explanation":"Un traitement anti-Chlamydia est systématique devant une gonococcie (urétrite mixte dans 15 % des cas). Le traitement minute, en dose unique délivré sur place, est recommandé.","src":"p. 182"},{"id":"d162-qroc-011","type":"QROC","rank":"B","objective":"d162-obj-20","tags":["traitement"],"difficulty":1,"question":"Quel antibiotique, en injection IM unique de 1000 mg, est le traitement de première intention d'une gonococcie non compliquée ?","answer":"La ceftriaxone (1000 mg en IM unique)","accept":["ceftriaxone","ceftriaxone 1000 mg","ceftriaxone 1 g"],"keywords":["ceftriaxone"],"explanation":"Première intention : ceftriaxone 1000 mg IM unique (IV si anomalie de l'hémostase). En cas d'allergie aux bêta-lactamines : azithromycine 2 g, gentamicine 240 mg IM ou ciprofloxacine 500 mg (avec antibiogramme), en dose unique.","src":"p. 182"},{"id":"d162-qroc-012","type":"QROC","rank":"A","objective":"d162-obj-03","tags":["prévention","traitement"],"difficulty":1,"question":"Pendant combien de temps les rapports sexuels doivent-ils être évités ou protégés après le traitement d'une gonococcie ?","answer":"Au moins 7 jours","accept":["au moins 7 jours","7 jours","1 semaine","une semaine"],"keywords":["7 jours"],"explanation":"Les rapports doivent être évités ou protégés pendant au moins 7 jours, et le (la, les) partenaire(s) doivent être traités.","src":"p. 182"},{"id":"d162-qroc-013","type":"QROC","rank":"A","objective":"d162-obj-04","tags":["traitement","prévention"],"difficulty":1,"question":"Dans la gonococcie, que doit-on faire systématiquement pour le (la, les) partenaire(s) ?","answer":"Les traiter (après les avoir identifiés et leur avoir proposé un dépistage)","accept":["les traiter","traiter les partenaires","traitement du partenaire","traitement des partenaires","traiter le partenaire"],"keywords":["trait"],"explanation":"Le traitement des partenaires est systématique. Comme pour toute IST, on identifie les partenaires contaminés ou contaminateurs et on leur propose dépistage, diagnostic et/ou traitement probabiliste.","src":"p. 182"},{"id":"d162-qroc-014","type":"QROC","rank":"A","objective":"d162-obj-15","tags":["paraclinique","prévention"],"difficulty":1,"question":"Devant une IST, quels trois dépistages associés doit-on proposer systématiquement au patient ?","answer":"Sérologie VIH, test tréponémique (syphilis) et sérologie de l'hépatite B","accept":["vih, test tréponémique et hépatite b","vih tt hépatite b","vih, syphilis, hépatite b","vih syphilis hepatite b"],"keywords":["vih","hépatite b","trépon"],"explanation":"Devant toute IST (gonococcie, chlamydiose, trichomonose…), on propose une sérologie VIH, un test tréponémique et une sérologie de l'hépatite B, en plus des prélèvements du site atteint.","src":"p. 182, 185, 208"},{"id":"d162-qroc-015","type":"QROC","rank":"A","objective":"d162-obj-22","tags":["prévention"],"difficulty":1,"question":"Quelle prophylaxie contre le VIH peut-on envisager chez un patient atteint d'IST qui prend des risques trop réguliers ?","answer":"La PrEP (prophylaxie pré-exposition)","accept":["prep","prophylaxie pré-exposition","prophylaxie pre exposition","prophylaxie préexposition"],"keywords":["prep"],"explanation":"Un traitement de type PrEP peut être envisagé en cas de prises de risque trop régulières. Il s'ajoute à l'éducation sur les IST et au rappel des risques de recontamination.","src":"p. 182, 185"},{"id":"d162-qroc-016","type":"QROC","rank":"A","objective":"d162-obj-35","tags":["clinique","pièges"],"difficulty":2,"question":"Quel caractère de l'infection à C. trachomatis (50 % des cas chez l'homme, 50 à 90 % chez la femme) entretient la chaîne épidémiologique et favorise les complications tardives ?","answer":"Le portage asymptomatique","accept":["portage asymptomatique","asymptomatique","forme asymptomatique","infection asymptomatique"],"keywords":["asymptomatique"],"explanation":"Le portage asymptomatique est très fréquent : il maintient la chaîne de transmission et laisse évoluer silencieusement les complications tardives. La cervicite est la forme la plus fréquente chez la femme, le plus souvent asymptomatique.","src":"p. 184"},{"id":"d162-qroc-017","type":"QROC","rank":"A","objective":"d162-obj-08","tags":["clinique"],"difficulty":2,"question":"Quel est l'aspect habituel de l'écoulement urétral (présent dans moins de 50 % des cas) au cours d'une urétrite à C. trachomatis ?","answer":"Clair, modéré et intermittent","accept":["clair","écoulement clair","clair modéré et intermittent","clair, modéré, intermittent"],"keywords":["clair"],"explanation":"L'écoulement de la chlamydiose est présent dans moins de 50 % des cas et le plus souvent clair, modéré et intermittent. Il contraste avec l'écoulement purulent de la gonococcie.","src":"p. 184, 186"},{"id":"d162-qroc-018","type":"QROC","rank":"A","objective":"d162-obj-15","tags":["paraclinique","pièges"],"difficulty":2,"question":"Quel est l'intérêt de la sérologie dans le diagnostic d'une infection à Chlamydia trachomatis ?","answer":"Aucun","accept":["aucun","aucun intérêt","pas d'intérêt","pas d interet","inutile"],"keywords":["aucun"],"explanation":"La sérologie n'a pas d'intérêt pour le diagnostic de C. trachomatis : l'examen clé est la PCR, plus sensible que la culture.","src":"p. 185"},{"id":"d162-qroc-019","type":"QROC","rank":"A","objective":"d162-obj-18","tags":["traitement","pièges"],"difficulty":2,"question":"Pourquoi le traitement minute de C. trachomatis par azithromycine en dose unique est-il remis en question ?","answer":"Émergence de résistances de Mycoplasma genitalium à l'azithromycine","accept":["résistance de mycoplasma genitalium","resistances de mycoplasma genitalium","résistances de mycoplasma genitalium à l'azithromycine","mycoplasma genitalium résistant à l'azithromycine"],"keywords":["mycoplasma","résistance"],"explanation":"L'azithromycine en dose unique favorise l'émergence de résistances chez d'autres micro-organismes, notamment Mycoplasma genitalium. D'où la préférence donnée à la doxycycline sur 7 jours.","src":"p. 185, 187"},{"id":"d162-qroc-020","type":"QROC","rank":"A","objective":"d162-obj-18","tags":["traitement"],"difficulty":2,"question":"Plutôt que le traitement minute par azithromycine, quelle association d'antibiotiques privilégier devant une urétrite en traitement probabiliste ?","answer":"Doxycycline pendant 7 jours + ceftriaxone en 1 injection","accept":["doxycycline et ceftriaxone","doxycycline + ceftriaxone","ceftriaxone et doxycycline","ceftriaxone + doxycycline","doxycycline 7 jours ceftriaxone"],"keywords":["doxycycline","ceftriaxone"],"explanation":"Il est préférable de donner la doxycycline pendant 7 jours (anti-Chlamydia) associée à une injection de ceftriaxone (anti-gonocoque).","src":"p. 187"},{"id":"d162-qroc-021","type":"QROC","rank":"B","objective":"d162-obj-35","tags":["complications","épidémiologie"],"difficulty":2,"question":"De quelle complication tubaire C. trachomatis est-il responsable dans 70 % des cas ?","answer":"La stérilité tubaire","accept":["stérilité tubaire","sterilite tubaire","stérilités tubaires","infertilité tubaire"],"keywords":["stérilité"],"explanation":"C. trachomatis est responsable de 50 % des salpingites de la femme jeune et de 70 % des stérilités tubaires, avec aussi un risque d'algies pelviennes inflammatoires et de grossesse extra-utérine.","src":"p. 183"},{"id":"d162-qroc-022","type":"QROC","rank":"B","objective":"d162-obj-02","tags":["épidémiologie","prévention"],"difficulty":1,"question":"Quelle population féminine bénéficie en France d'un dépistage systématique de C. trachomatis par autoprélèvement vaginal ?","answer":"Les femmes de moins de 25 ans","accept":["moins de 25 ans","femmes de moins de 25 ans","15 à 25 ans","15-25 ans"],"keywords":["25 ans"],"explanation":"Le dépistage systématique par autoprélèvement vaginal vise les femmes de moins de 25 ans. Au-delà, il est opportuniste et ciblé sur les facteurs de risque, comme chez les hommes sexuellement actifs à risque.","src":"p. 183, 187"},{"id":"d162-qroc-023","type":"QROC","rank":"B","objective":"d162-obj-14","tags":["complications","clinique"],"difficulty":2,"question":"Quelle complication systémique de la gonococcie associe fièvre, atteinte cutanée acrale (purpura pétéchial, papulo-pustules) et mono- ou oligo-arthrites septiques ?","answer":"La septicémie gonococcique","accept":["septicémie gonococcique","septicemie gonococcique","septicémie à gonocoque"],"keywords":["septicémie"],"explanation":"La septicémie gonococcique est une complication systémique : elle impose l'hospitalisation et un traitement IV par ceftriaxone 1 g/jour pendant 7 à 10 jours. Plus rarement : péri-hépatite, endocardite ou méningite.","src":"p. 181-182"},{"id":"d162-qroc-024","type":"QROC","rank":"A","objective":"d162-obj-20","tags":["traitement","pièges"],"difficulty":1,"question":"Pourquoi les schémas thérapeutiques des infections à gonocoque doivent-ils être régulièrement réactualisés ?","answer":"Émergence de souches résistantes aux antibiotiques","accept":["résistance aux antibiotiques","souches résistantes","résistances aux antibiotiques","émergence de résistances"],"keywords":["résistan"],"explanation":"La sensibilité du gonocoque aux antibiotiques diminue : l'émergence de souches résistantes impose d'adapter régulièrement les schémas. La culture avec antibiogramme permet de suivre ces résistances.","src":"p. 180, 182, 187"},{"id":"d162-qru-101","type":"QRU","rank":"A","objective":"d162-obj-07","tags":["diagnostic","clinique"],"difficulty":1,"stem":"Un homme de 28 ans consulte pour une ulcération de 8 mm du sillon balano-préputial, apparue 3 semaines après un rapport non protégé. Elle est à fond propre et rosé, indolore, indurée, avec une adénopathie satellite unilatérale non inflammatoire. Quel est le diagnostic le plus probable ?","options":[{"t":"Maladie de Nicolas-Favre","ok":false,"why":"Elle évoque plutôt une anorectite, des ulcérations anogénitales et des diarrhées trompeuses."},{"t":"Herpès génital","ok":false,"why":"L'herpès donne des ulcérations superficielles douloureuses à contours polycycliques."},{"t":"Donovanose","ok":false,"why":"Elle donne des lésions granulomateuses peu douloureuses, sur un terrain particulier (sujets africains)."},{"t":"Chancre mou","ok":false,"why":"Il est douloureux, à fond sale, avec des adénopathies inflammatoires."},{"t":"Chancre syphilitique","ok":true,"why":"Ulcération indurée, indolore, à fond propre, avec adénopathie satellite non inflammatoire, après environ 3 semaines d'incubation : syphilis primaire."}],"explanation":"L'induration est le seul caractère vraiment évocateur du chancre syphilitique, et l'absence de douleur le distingue de l'herpès. Toute ulcération muqueuse aiguë doit de toute façon faire évoquer la syphilis.","src":"p. 188-190, 197"},{"id":"d162-qru-102","type":"QRU","rank":"A","objective":"d162-obj-18","tags":["traitement","pièges"],"difficulty":2,"stem":"Une femme de 31 ans consulte pour une ulcération vulvaire indolore et indurée, apparue il y a 4 jours après un rapport non protégé. L'ELISA et le VDRL sont tous deux négatifs. Quelle est la meilleure attitude ?","options":[{"t":"Conclure à une fausse sérologie syphilitique","ok":false,"why":"Une fausse sérologie correspond à un TNT positif isolé, pas à deux tests négatifs."},{"t":"Traiter d'emblée, sans attendre la sérologie","ok":true,"why":"Devant une ulcération génitale, on ne doit pas attendre les résultats ; TT et TNT peuvent être négatifs pendant les 7 premiers jours du chancre."},{"t":"Attendre une deuxième sérologie avant tout traitement","ok":false,"why":"L'OMS recommande de ne pas attendre les résultats des tests pour traiter une ulcération génitale."},{"t":"Prescrire de la doxycycline pendant 14 jours","ok":false,"why":"La doxycycline est réservée aux patients allergiques à la pénicilline."},{"t":"Éliminer la syphilis puisque la sérologie est négative","ok":false,"why":"Dans les 7 premiers jours du chancre, les deux tests peuvent encore être négatifs."}],"explanation":"Le traitement de la syphilis précoce repose sur une injection IM unique de benzathine-benzylpénicilline 2,4 MU. La sérologie reste utile, mais elle ne doit pas retarder le traitement.","trap":"Une sérologie négative ne dispense pas de traiter un chancre récent.","src":"p. 194-198"},{"id":"d162-qru-103","type":"QRU","rank":"A","objective":"d162-obj-18","tags":["traitement"],"difficulty":2,"stem":"Un homme de 24 ans a un écoulement urétral purulent avec brûlures mictionnelles depuis 3 jours, après un rapport non protégé. Quel traitement probabiliste doit-on privilégier ?","options":[{"t":"Ceftriaxone en 1 injection + doxycycline pendant 7 jours","ok":true,"why":"Anti-gonocoque (ceftriaxone) et anti-Chlamydia associés systématiquement (urétrite mixte dans 15 % des cas) ; la doxycycline 7 jours est préférée à l'azithromycine en dose unique."},{"t":"Ceftriaxone en injection IM unique, sans autre antibiotique","ok":false,"why":"Il faut aussi traiter C. trachomatis, car l'urétrite est mixte dans 15 % des cas."},{"t":"Doxycycline pendant 7 jours, sans autre antibiotique","ok":false,"why":"Elle ne traite pas le gonocoque : la ceftriaxone est nécessaire."},{"t":"Azithromycine 1 g en prise orale unique, sans autre antibiotique","ok":false,"why":"C'est une option anti-Chlamydia, pas le traitement de première intention du gonocoque ; le traitement minute est d'ailleurs remis en question."},{"t":"Attendre les résultats de la PCR avant tout traitement","ok":false,"why":"Un traitement probabiliste immédiat, délivré sur place, est recommandé."}],"explanation":"Devant une urétrite aiguë, on traite d'emblée le gonocoque et C. trachomatis, on traite le(s) partenaire(s) et on propose sérologie VIH, test tréponémique et sérologie de l'hépatite B.","src":"p. 182, 187"},{"id":"d162-qru-104","type":"QRU","rank":"A","objective":"d162-obj-27","tags":["biologie","pièges"],"difficulty":2,"stem":"Une patiente de 34 ans, atteinte d'un lupus érythémateux systémique, est asymptomatique. Un bilan systématique montre un VDRL positif et un test tréponémique (ELISA) négatif. Quelle est l'interprétation la plus probable ?","options":[{"t":"Syphilis secondaire","ok":false,"why":"Au stade secondaire, le TT et le TNT sont toujours positifs."},{"t":"Syphilis très ancienne non traitée","ok":false,"why":"Elle donne un TT positif."},{"t":"Cicatrice sérologique d'une syphilis traitée","ok":false,"why":"Une cicatrice sérologique donne un TT positif et un TNT négatif, l'inverse du profil observé."},{"t":"Fausse sérologie syphilitique liée au lupus","ok":true,"why":"Un TNT positif isolé est en général une fausse sérologie (lupus, syndrome des anticorps anti-phospholipides, grossesse)."},{"t":"Tréponématose endémique non vénérienne","ok":false,"why":"Ces infections positivent le test tréponémique, ce qui n'est pas le cas ici."}],"explanation":"On interprète d'abord le TT : négatif, il signifie l'absence de tréponématose ou une tréponématose guérie. Un TNT positif isolé évoque une fausse sérologie ; le TNT ne se positive avant le TT que dans 10 % des cas.","src":"p. 194-196"},{"id":"d162-qru-105","type":"QRU","rank":"A","objective":"d162-obj-36","tags":["clinique","pièges"],"difficulty":2,"stem":"Une fillette de 4 ans est examinée pour des condylomes anogénitaux. Quelle affirmation est exacte ?","options":[{"t":"Une biopsie systématique est indiquée","ok":false,"why":"La biopsie est réservée aux doutes diagnostiques et aux suspicions de néoplasie."},{"t":"Ils sont le plus souvent d'origine manuportée","ok":true,"why":"La contamination vient souvent de verrues vulgaires ou de linges domestiques ; une transmission mère-enfant est possible."},{"t":"Ils prouvent l'existence de sévices sexuels, qu'il faut signaler","ok":false,"why":"Ils sont un mauvais marqueur de sévices sexuels, même s'il faut rester vigilant."},{"t":"Le traitement de référence est la podophyllotoxine","ok":false,"why":"La podophyllotoxine est contre-indiquée chez la femme enceinte et chez l'enfant."},{"t":"Ils sont toujours d'origine sexuelle chez l'enfant","ok":false,"why":"Chez l'enfant, la contamination est le plus souvent manuportée ; une transmission mère-enfant est aussi possible."}],"explanation":"Chez l'enfant, les condylomes sont le plus souvent d'origine manuportée (verrues vulgaires, linges). Leur présence est un mauvais marqueur de sévices sexuels.","src":"p. 201, 203, 205"},{"id":"d162-qru-106","type":"QRU","rank":"A","objective":"d162-obj-27","tags":["biologie"],"difficulty":2,"stem":"Un patient de 45 ans, traité il y a 8 ans pour une syphilis, est asymptomatique. Son ELISA est positif et son VDRL négatif. Quelle est l'interprétation la plus probable ?","options":[{"t":"Fausse sérologie syphilitique","ok":false,"why":"Elle correspond à un TNT positif isolé, avec un TT négatif."},{"t":"Absence de toute tréponématose","ok":false,"why":"Il faudrait un TT négatif pour l'affirmer."},{"t":"Syphilis secondaire en phase évolutive","ok":false,"why":"Au stade secondaire, le TT et le TNT sont toujours positifs, avec un titre élevé."},{"t":"Cicatrice sérologique","ok":true,"why":"Un TT positif avec un TNT négatif traduit une tréponématose guérie (cicatrice sérologique)."},{"t":"Recontamination syphilitique récente","ok":false,"why":"Elle se reconnaît à une remontée significative du TNT quantitatif (titre multiplié par 4 au moins)."}],"explanation":"Le TT reste positif à vie après une tréponématose, alors que le TNT se négative sous traitement efficace : le profil TT positif / TNT négatif est celui de la cicatrice sérologique.","src":"p. 195"},{"id":"d162-qru-107","type":"QRU","rank":"A","objective":"d162-obj-23","tags":["diagnostic","définition"],"difficulty":2,"stem":"Un homme de 29 ans, asymptomatique, a un ELISA positif lors d'un dépistage. Il fournit une sérologie syphilitique négative datant de 8 mois. Quel est le diagnostic ?","options":[{"t":"Syphilis tertiaire","ok":false,"why":"Elle appartient aux syphilis tardives, comme la latente tardive."},{"t":"Syphilis latente précoce","ok":true,"why":"Sérologie positive sans lésion clinique, avec une sérologie négative de moins de 1 an : syphilis latente précoce."},{"t":"Syphilis secondaire","ok":false,"why":"Il n'y a ni éruption ni signe général."},{"t":"Syphilis primaire","ok":false,"why":"Il n'y a pas de chancre : le patient est asymptomatique."},{"t":"Syphilis latente tardive","ok":false,"why":"Elle est non datable ou date de plus de 1 an."}],"explanation":"La syphilis précoce regroupe la syphilis primaire, secondaire et latente précoce. Le diagnostic de latente précoce n'est acceptable que si le patient fournit une sérologie négative de moins de 1 an. Le traitement est le même que pour les autres formes précoces.","src":"p. 188, 197"},{"id":"d162-qcm-101","type":"QRM","rank":"A","objective":"d162-obj-08","tags":["clinique","diagnostic"],"difficulty":1,"stem":"Un homme de 22 ans consulte pour un écoulement urétral purulent avec dysurie depuis 3 jours, après un rapport non protégé il y a 4 jours. Quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"Le portage asymptomatique urétral est fréquent chez l'homme","ok":false,"why":"Il est exceptionnel à l'urètre : le tableau est le plus souvent bruyant."},{"t":"Le traitement diffère en cas d'infection par le VIH","ok":false,"why":"Le traitement des urétrites est identique en cas d'infection par le VIH."},{"t":"L'écoulement est le plus souvent clair et intermittent","ok":false,"why":"C'est l'aspect de la chlamydiose ; l'écoulement gonococcique est purulent dans 90 % des cas."},{"t":"Il faut attendre le résultat de la culture avant de traiter","ok":false,"why":"Le traitement minute, en dose unique, est délivré sur place lors de la consultation."},{"t":"Une incubation de 2 à 7 jours oriente vers une gonococcie","ok":true,"why":"L'incubation de la gonococcie est de 2 à 7 jours, alors que celle de la chlamydiose est variable (quelques jours à quelques mois)."}],"explanation":"Urétrite aiguë purulente après une incubation courte : gonococcie jusqu'à preuve du contraire. On associe un traitement anti-Chlamydia et on traite le(s) partenaire(s).","src":"p. 180, 182"},{"id":"d162-qcm-102","type":"QRM","rank":"A","objective":"d162-obj-10","tags":["clinique","diagnostic"],"difficulty":2,"stem":"À propos des infections génitales à Chlamydia trachomatis, quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"La sérologie est l'examen de référence du diagnostic","ok":false,"why":"La sérologie n'a pas d'intérêt ; l'examen clé est la PCR."},{"t":"L'écoulement urétral est constant et franchement purulent","ok":false,"why":"Il est présent dans moins de 50 % des cas, le plus souvent clair, modéré et intermittent."},{"t":"Le portage asymptomatique est fréquent","ok":true,"why":"Il concerne 50 % des hommes et 50 à 90 % des femmes, et entretient la chaîne épidémiologique."},{"t":"La culture est plus sensible que la PCR","ok":false,"why":"C'est la PCR qui est plus sensible que la culture."},{"t":"La cervicite est une forme rare chez la femme","ok":false,"why":"C'est la forme la plus fréquente des chlamydioses urogénitales basses de la femme."}],"explanation":"La chlamydiose est volontiers silencieuse, ce qui explique la diffusion dans la population et les complications tardives. Le diagnostic repose sur la PCR.","src":"p. 184-185"},{"id":"d162-qcm-103","type":"QRM","rank":"A","objective":"d162-obj-15","tags":["paraclinique"],"difficulty":2,"stem":"Quels prélèvements sont adaptés à la recherche par PCR d'un gonocoque et de C. trachomatis ?","options":[{"t":"Chez l'homme, le 1er jet urinaire, au moins 2 h après la dernière miction","ok":true,"why":"C'est le prélèvement recommandé chez l'homme, symptomatique ou non."},{"t":"Un prélèvement pharyngé et/ou anal, selon les pratiques sexuelles","ok":true,"why":"Les sites extragénitaux sont à prélever selon les pratiques, dans les deux sexes."},{"t":"Une sérologie sanguine en première intention","ok":false,"why":"La sérologie n'a pas d'intérêt pour C. trachomatis ; le diagnostic repose sur la PCR."},{"t":"Des urines du milieu de jet, recueillies juste après une miction","ok":false,"why":"Il faut un 1er jet, au moins 2 heures après la dernière miction."},{"t":"Chez la femme, un auto-écouvillonnage vaginal","ok":true,"why":"Il est à préférer à l'écouvillonnage de l'endocol réalisé par un professionnel."}],"explanation":"La PCR (souvent biplex gonocoque + C. trachomatis) se fait sur 1er jet urinaire chez l'homme et auto-écouvillonnage vaginal chez la femme, avec prélèvements pharyngé et/ou anal selon les pratiques sexuelles.","src":"p. 181, 185"},{"id":"d162-qcm-104","type":"QRM","rank":"A","objective":"d162-obj-07","tags":["clinique","pièges"],"difficulty":2,"stem":"À propos du chancre de la syphilis primaire, quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"Il est pathognomonique : sa présence suffit à conclure","ok":false,"why":"Aucune de ses caractéristiques n'est pathognomonique."},{"t":"Il est typiquement douloureux, comme l'herpès","ok":false,"why":"Il est indolore, à la différence de l'herpès."},{"t":"Il est toujours unique : il n'est jamais multiple","ok":false,"why":"Il est le plus souvent unique mais peut être multiple, avec des images en miroir."},{"t":"L'induration est son seul signe vraiment évocateur","ok":true,"why":"La lésion ne peut être plissée entre deux doigts : elle ne fait qu'un bloc avec l'induration sous-jacente."},{"t":"Il est toujours visible, donc jamais méconnu","ok":false,"why":"Il est souvent méconnu quand il siège au vagin, au col utérin, à l'anorectum ou au pharynx."}],"explanation":"Le chancre est une exulcération à fond propre, rosée, indolore, indurée, accompagnée d'une adénopathie non inflammatoire. Comme aucun signe n'est pathognomonique, on évoque la syphilis devant toute ulcération muqueuse aiguë.","src":"p. 188-189"},{"id":"d162-qcm-105","type":"QRM","rank":"B","objective":"d162-obj-25","tags":["clinique"],"difficulty":2,"stem":"Parmi les manifestations suivantes, lesquelles peuvent s'observer au cours d'une syphilis secondaire ?","options":[{"t":"Ulcération douloureuse à fond sale avec adénopathies inflammatoires","ok":false,"why":"Cela évoque un chancre mou."},{"t":"Condylomes acuminés en « crêtes-de-coq »","ok":false,"why":"Ce sont des lésions à HPV ; les syphilides génitales (condylomata lata) font partie de leur diagnostic différentiel."},{"t":"Fausse perlèche (papule commissurale fendue en deux)","ok":true,"why":"Elle diffère d'une simple fissure sans relief du fond du pli."},{"t":"Alopécie en aires incomplètement dépilées, dite en « fourrure mitée »","ok":true,"why":"Elle fait partie des signes cutanéo-phanériens, comme la dépilation des sourcils."},{"t":"Dépapillation de la langue en aires (plaques « fauchées »)","ok":true,"why":"Elle fait partie des symptômes cutanéo-phanériens plus trompeurs."}],"explanation":"La syphilis secondaire, « grande simulatrice », associe des éruptions polymorphes (roséole, syphilides papuleuses cuivrées, palmo-plantaires) et des signes plus discrets : fausse perlèche, plaques fauchées, dépilation des sourcils, fourrure mitée.","src":"p. 192-193, 197, 203"},{"id":"d162-qcm-106","type":"QRM","rank":"A","objective":"d162-obj-27","tags":["biologie","diagnostic"],"difficulty":2,"stem":"Un patient présente une éruption papuleuse cuivrée avec des papules palmo-plantaires évoquant une syphilis secondaire. Quels résultats sérologiques attend-on ?","options":[{"t":"Un TNT positif, avec un titre élevé","ok":true,"why":"Le TNT atteint un plateau durant la phase secondaire, en général entre 1/16 et 1/128."},{"t":"Un test tréponémique positif avec un TNT négatif","ok":false,"why":"C'est le profil d'une cicatrice sérologique ou d'une syphilis très précoce."},{"t":"Un test tréponémique positif","ok":true,"why":"Au stade secondaire, le TT et le TNT sont toujours positifs."},{"t":"Un test tréponémique négatif avec un TNT positif","ok":false,"why":"Ce profil évoque une fausse sérologie syphilitique."},{"t":"Deux tests négatifs","ok":false,"why":"Cela n'est possible que dans les 7 premiers jours du chancre."}],"explanation":"En syphilis secondaire, les deux tests sont positifs et le titre du TNT est élevé. Un TNT très positif traduit une maladie évolutive.","src":"p. 195-196, 200"},{"id":"d162-qcm-107","type":"QRM","rank":"A","objective":"d162-obj-28","tags":["suivi"],"difficulty":2,"stem":"Un patient est traité par benzathine-benzylpénicilline pour une syphilis primaire. Quelle(s) proposition(s) concernant le suivi est/sont exacte(s) ?","options":[{"t":"Le suivi se fait sur le TNT quantitatif : titre divisé par 4 à 6 mois","ok":true,"why":"Sans cette décroissance, l'avis d'un spécialiste est justifié et le traitement est repris."},{"t":"Le suivi se fait sur le titre du test tréponémique quantitatif, qui doit se négativer","ok":false,"why":"Le TT quantitatif varie beaucoup d'un examen à l'autre : ce n'est pas un bon marqueur d'évolutivité."},{"t":"Le TNT doit déjà être négatif dès le 1er mois suivant le traitement","ok":false,"why":"Il doit être négatif 1 an après le traitement d'une syphilis primaire, et dans les 2 ans pour une syphilis secondaire."},{"t":"Un contrôle unique à 3 mois est suffisant pour conclure à la guérison","ok":false,"why":"Les contrôles ont lieu à 3 mois, 6 mois, 1 an, puis tous les ans jusqu'à négativation."},{"t":"Une remontée du TNT ne peut pas évoquer une recontamination","ok":false,"why":"La maladie n'est pas immunisante : un titre multiplié au moins par 4 évoque une recontamination."}],"explanation":"Contrôle clinique et biologique à 3 mois, 6 mois, 1 an puis annuel jusqu'à négativation, sur le TNT quantitatif (VDRL). Le patient a un comportement sexuel à haut risque : on cherche une IST associée et on répète la prévention.","src":"p. 195, 198"},{"id":"d162-qcm-108","type":"QRM","rank":"A","objective":"d162-obj-30","tags":["diagnostic","prévention"],"difficulty":2,"stem":"Une femme de 24 ans consulte pour des condylomes acuminés vulvaires. Quelle(s) mesure(s) est/sont indiquée(s) ?","options":[{"t":"Une biopsie systématique de chaque condylome","ok":false,"why":"La biopsie n'est faite qu'en cas de doute diagnostique ou de suspicion de néoplasie."},{"t":"Un test HPV-HR en première intention, quel que soit l'âge","ok":false,"why":"Il est recommandé à partir de 30 ans ; avant, il est presque toujours positif sans pathologie sous-jacente."},{"t":"Un examen gynécologique et anal complet","ok":true,"why":"Les formes multifocales (vagin, périnée, région péri-anale) l'imposent, avec un dépistage cervical."},{"t":"Un traitement antibiotique par ceftriaxone","ok":false,"why":"Il n'existe pas de traitement spécifique des infections à HPV ; on vise la disparition des lésions visibles."},{"t":"Une recherche d'IST associée (VIH, syphilis, hépatite B, PCR)","ok":true,"why":"Une autre IST est présente dans 25 % des cas en moyenne : sérologie VIH, test tréponémique, hépatite B, PCR Chlamydia et gonocoque."}],"explanation":"Le diagnostic est clinique. Chez la femme, l'atteinte multifocale impose un examen gynécologique et anal complet, un dépistage cervical (frottis avant 30 ans) et la recherche d'une IST associée.","src":"p. 201-202, 204-205"},{"id":"d162-qcm-109","type":"QRM","rank":"A","objective":"d162-obj-22","tags":["prévention"],"difficulty":2,"stem":"À propos de la vaccination anti-HPV, quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"Elle n'est pas recommandée chez les HSH","ok":false,"why":"Elle est recommandée chez les HSH jusqu'à 26 ans, en prévention des lésions anales, des cancers anaux et des condylomes."},{"t":"Elle s'adresse aux filles comme aux garçons","ok":true,"why":"Elle est proposée à tous les adolescents, entre 11 et 14 ans, avec rattrapage de 15 à 19 ans révolus."},{"t":"Elle est surtout efficace lorsqu'elle est faite après la contamination","ok":false,"why":"Elle est avant tout préventive et se fait au mieux avant toute contamination."},{"t":"Elle est contre-indiquée chez les patients immunodéprimés","ok":false,"why":"Elle est recommandée chez les immunodéprimés, garçons comme filles, avec rattrapage jusqu'à 19 ans révolus."},{"t":"Toute nouvelle vaccination commence par un vaccin ciblant seulement les HPV 6, 11, 16 et 18","ok":false,"why":"Toute nouvelle vaccination doit être initiée avec le vaccin nonavalent."}],"explanation":"Vaccin nonavalent (Gardasil 9) pour tous : 2 doses espacées de 6 à 13 mois entre 11 et 14 ans, 3 doses (0, 2, 6 mois) de 15 à 19 ans et chez les HSH jusqu'à 26 ans.","src":"p. 204-205"},{"id":"d162-qcm-110","type":"QRM","rank":"A","objective":"d162-obj-05","tags":["diagnostic","étiologie"],"difficulty":2,"stem":"Parmi les propositions suivantes sur les causes d'ulcération génitale, lesquelles sont exactes ?","options":[{"t":"La maladie de Nicolas-Favre se limite à un chancre isolé du gland","ok":false,"why":"Elle associe anorectite, ulcérations anogénitales et diarrhées trompeuses."},{"t":"Le chancre syphilitique est typiquement douloureux, à fond sale","ok":false,"why":"Il est indolore, à fond propre."},{"t":"La donovanose donne des ulcérations très douloureuses","ok":false,"why":"Ses lésions granulomateuses sont peu douloureuses."},{"t":"L'herpès : ulcérations superficielles, douloureuses, polycycliques","ok":true,"why":"C'est la description de l'herpès, à distinguer du chancre syphilitique indolore."},{"t":"Le chancre mou est douloureux, à fond sale","ok":true,"why":"Il s'accompagne d'adénopathies inflammatoires, sur un terrain particulier (sujets africains), avec des lésions uniques ou multiples."}],"explanation":"Devant une ulcération génitale, on évoque systématiquement la syphilis et on élimine l'herpès, le chancre mou, la donovanose et la maladie de Nicolas-Favre.","src":"p. 188, 197"},{"id":"d162-qcm-111","type":"QRM","rank":"B","objective":"d162-obj-15","tags":["paraclinique","diagnostic"],"difficulty":2,"stem":"Concernant le diagnostic microbiologique de la gonococcie, quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"La PCR fournit aussi la sensibilité de la souche aux différents antibiotiques","ok":false,"why":"Elle ne permet pas de tester la sensibilité de la souche, d'où l'intérêt de la culture."},{"t":"Examen direct : diplocoques à Gram négatif intracellulaires, « en grains de café »","ok":true,"why":"Sa sensibilité et sa spécificité dépassent 95 % dans l'urétrite masculine symptomatique."},{"t":"Un diplocoque extracellulaire à Gram négatif suffit à affirmer le diagnostic","ok":false,"why":"Il existe des Neisseria non pathogènes : cet aspect ne donne pas de certitude."},{"t":"L'examen direct est aussi performant chez la femme que dans l'urétrite masculine","ok":false,"why":"Sensibilité et spécificité sont moins bonnes pour les autres sites et chez la femme."},{"t":"La culture sur gélose au sang cuit est systématique, avec antibiogramme en 24-48 h","ok":true,"why":"Elle confirme le diagnostic et permet de suivre les résistances."}],"explanation":"En cas de symptômes, on peut faire un examen direct et une culture sur écoulement urétral (ou 1er jet urinaire) ; en dépistage, la PCR est préconisée.","src":"p. 181-182"},{"id":"d162-qcm-112","type":"QRM","rank":"B","objective":"d162-obj-34","tags":["traitement"],"difficulty":2,"stem":"Concernant le traitement d'une infection non compliquée à Chlamydia trachomatis, quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"L'azithromycine 1 g en dose unique, si risque de mauvaise observance","ok":true,"why":"Elle a l'avantage de la dose unique, mais favorise des résistances chez d'autres micro-organismes (Mycoplasma genitalium)."},{"t":"Le contrôle par PCR ne doit pas être trop précoce","ok":true,"why":"Des débris cellulaires dans les 4 semaines suivant le traitement peuvent rendre la PCR faussement positive."},{"t":"La doxycycline 7 jours est un traitement de 1re intention","ok":true,"why":"Le schéma est de 100 mg toutes les 12 heures par voie orale pendant 7 jours."},{"t":"L'érythromycine est le traitement de première intention","ok":false,"why":"L'érythromycine (ou l'ofloxacine) est un traitement de deuxième intention."},{"t":"Les cyclines sont recommandées chez la femme enceinte","ok":false,"why":"Chez la femme enceinte, on prescrit l'azithromycine 1 g en prise unique, avec une PCR de contrôle à 1 mois."}],"explanation":"Doxycycline 7 jours en première intention, azithromycine en dose unique si risque d'inobservance ; contrôle PCR différé de plusieurs semaines.","src":"p. 185-186"},{"id":"d162-qcm-113","type":"QRM","rank":"B","objective":"d162-obj-31","tags":["traitement"],"difficulty":2,"stem":"Concernant le traitement des condylomes, quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"La podophyllotoxine est contre-indiquée chez la femme enceinte et chez l'enfant","ok":true,"why":"Elle est appliquée par le patient matin et soir, 3 jours consécutifs par semaine, sur les lésions seulement."},{"t":"Les méthodes de destruction physique n'ont pas de risque cicatriciel","ok":false,"why":"Cryothérapie, laser CO2 et électrocoagulation ont en commun un risque cicatriciel."},{"t":"Pas de traitement spécifique de l'HPV : on vise la disparition des lésions visibles","ok":true,"why":"Le risque de récidive est important car le virus peut persister dans l'épiderme sain."},{"t":"La cryothérapie est idéale pour les lésions étendues","ok":false,"why":"Elle ne se conçoit que pour des lésions d'étendue limitée, car elle est douloureuse."},{"t":"Après la disparition des lésions, le virus est éliminé de l'épiderme","ok":false,"why":"Le virus peut persister dans l'épiderme sain."}],"explanation":"Le traitement est adapté au type de lésion et à la localisation (destruction physique, chimique ou immunologique) ; un suivi à 1 mois puis tous les 3 mois jusqu'à guérison clinique est prévu.","src":"p. 204-205"},{"id":"d162-qcm-114","type":"QRM","rank":"A","objective":"d162-obj-28","tags":["traitement","pièges"],"difficulty":2,"stem":"Quelques heures après l'injection de benzathine-benzylpénicilline pour une syphilis secondaire, un patient présente fièvre, céphalées, myalgies et accentuation de son éruption. Quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"Elle signe l'échec du traitement","ok":false,"why":"L'efficacité du traitement se juge sur le TNT quantitatif à 6 mois."},{"t":"Il s'agit d'une réaction d'Herxheimer, bénigne, secondaire à la lyse des tréponèmes","ok":true,"why":"Elle est toujours bénigne ; un antipyrétique peut être prescrit."},{"t":"Un protocole thérapeutique permet de la prévenir de façon fiable","ok":false,"why":"Aucun protocole thérapeutique ne la prévient réellement ; on prévient le patient du risque."},{"t":"Il s'agit d'une allergie à la pénicilline : toute nouvelle injection est contre-indiquée","ok":false,"why":"La réaction d'Herxheimer ne doit pas être interprétée comme une allergie à la pénicilline."},{"t":"Il faut passer d'emblée à la doxycycline pendant 14 jours","ok":false,"why":"La doxycycline est réservée aux patients allergiques à la pénicilline."}],"explanation":"La réaction d'Herxheimer est possible quelques heures après l'injection au stade secondaire (bénigne dans la syphilis primaire). On prévient le patient et on peut prescrire un antipyrétique.","src":"p. 198"},{"id":"d162-qcm-115","type":"QRM","rank":"A","objective":"d162-obj-19","tags":["prévention","diagnostic"],"difficulty":2,"stem":"Concernant le dépistage des lésions cervicales liées aux HPV, quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"Le test HPV-HR est recommandé en première intention à partir de 30 ans","ok":true,"why":"Il permet le typage des HPV oncogènes, en particulier 16 et 18."},{"t":"Le frottis cervico-vaginal est à répéter tous les 10 ans","ok":false,"why":"Le dépistage systématique repose sur un frottis tous les 3 ans (ou un test HPV-HR)."},{"t":"Avant 30 ans, un test HPV-HR positif traduit presque toujours une lésion","ok":false,"why":"Avant 30 ans, la clairance spontanée n'est pas totale : le test est presque toujours positif sans pathologie sous-jacente."},{"t":"En cas de dysplasie mineure, on se contente d'une surveillance sans colposcopie","ok":false,"why":"En cas de dysplasie, même mineure, on réalise une colposcopie et si nécessaire une biopsie dirigée."},{"t":"Une biopsie du col est systématique avant tout frottis","ok":false,"why":"La biopsie est dirigée par la colposcopie (acide acétique à 5 % ou lugol) sur les zones suspectes."}],"explanation":"Dépistage systématique du col : frottis tous les 3 ans ou test HPV-HR (dès 30 ans) ; toute dysplasie, même mineure, conduit à la colposcopie.","src":"p. 202, 205"},{"id":"d162-qroc-201","type":"QROC","rank":"A","objective":"d162-obj-23","tags":["clinique"],"difficulty":1,"question":"Quelles sont les deux lésions qui caractérisent la syphilis primaire ?","answer":"Un chancre au point d'inoculation et une adénopathie satellite","accept":["chancre et adénopathie","chancre + adénopathie","chancre et adénopathie satellite","chancre d'inoculation et adénopathie"],"keywords":["chancre","adénopathie"],"explanation":"Le chancre est contagieux (riche en tréponèmes). Le diagnostic est souvent méconnu quand il n'est pas visible : chancre vaginal, du col utérin, anorectal ou pharyngé.","src":"p. 188"},{"id":"d162-qroc-202","type":"QROC","rank":"A","objective":"d162-obj-07","tags":["clinique","diagnostic"],"difficulty":2,"question":"Quel est le seul caractère sémiologique vraiment évocateur d'un chancre syphilitique ?","answer":"L'induration (base indurée)","accept":["induration","base indurée","induré","indurée","ulcération indurée"],"keywords":["indur"],"explanation":"Le chancre est une exulcération de 5 à 15 mm, à fond propre et rosé, indolore, le plus souvent unique. L'induration (lésion impossible à plisser entre deux doigts) est le seul signe vraiment évocateur, mais aucun signe n'est pathognomonique.","src":"p. 188-189"},{"id":"d162-qroc-203","type":"QROC","rank":"A","objective":"d162-obj-07","tags":["clinique","pièges"],"difficulty":1,"question":"Quel caractère fonctionnel distingue le chancre syphilitique d'une ulcération herpétique ?","answer":"Il est indolore (l'herpès est douloureux)","accept":["indolore","non douloureux","pas douloureux","sans douleur"],"keywords":["indolore"],"explanation":"Le chancre syphilitique est indolore, à la différence de l'herpès dont les ulcérations superficielles sont douloureuses.","src":"p. 188, 197"},{"id":"d162-qroc-204","type":"QROC","rank":"A","objective":"d162-obj-06","tags":["clinique","diagnostic"],"difficulty":2,"question":"Quel est l'aspect des ulcérations de l'herpès génital, diagnostic différentiel du chancre syphilitique ?","answer":"Ulcérations superficielles, douloureuses, à contours polycycliques","accept":["contours polycycliques","polycycliques","polycyclique","superficielles douloureuses à contours polycycliques"],"keywords":["polycycl"],"explanation":"Devant une ulcération génitale, on élimine l'herpès (superficielle, douloureuse, polycyclique), le chancre mou, la donovanose et la maladie de Nicolas-Favre.","src":"p. 197"},{"id":"d162-qroc-205","type":"QROC","rank":"A","objective":"d162-obj-05","tags":["diagnostic"],"difficulty":1,"question":"Devant quelle situation clinique doit-on évoquer systématiquement un chancre syphilitique ?","answer":"Toute ulcération muqueuse aiguë (génitale, orale ou anale)","accept":["ulcération muqueuse","toute ulcération muqueuse","ulcération muqueuse aiguë","ulcération génitale"],"keywords":["ulcération","muqueuse"],"explanation":"Aucune caractéristique du chancre n'est pathognomonique : toute ulcération muqueuse aiguë, génitale, orale ou anale, doit faire évoquer la syphilis.","src":"p. 189, 197"},{"id":"d162-qroc-206","type":"QROC","rank":"A","objective":"d162-obj-23","tags":["clinique"],"difficulty":2,"question":"Quelles sont les caractéristiques de l'adénopathie satellite du chancre syphilitique ?","answer":"Non inflammatoire, le plus souvent unilatérale","accept":["non inflammatoire","adénopathie non inflammatoire","non inflammatoire et unilatérale"],"keywords":["non inflammatoire"],"explanation":"L'adénopathie est non inflammatoire et le plus souvent unilatérale ; elle n'est pas visible quand le chancre siège au col utérin ou au rectum. Le chancre mou, lui, s'accompagne d'adénopathies inflammatoires.","src":"p. 190, 197"},{"id":"d162-qroc-207","type":"QROC","rank":"A","objective":"d162-obj-23","tags":["clinique"],"difficulty":1,"question":"Quelle couleur caractérise les papules de la syphilis secondaire ?","answer":"Cuivrée","accept":["cuivrée","cuivré","cuivre","couleur cuivrée","cuivrées"],"keywords":["cuivr"],"explanation":"Les éruptions de la syphilis secondaire sont polymorphes : il faut chercher des lésions papuleuses de couleur cuivrée. Les syphilides papuleuses peuvent toucher le visage, le tronc, les membres et les organes génitaux.","src":"p. 191, 200"},{"id":"d162-qroc-208","type":"QROC","rank":"A","objective":"d162-obj-23","tags":["clinique"],"difficulty":2,"question":"Quelle localisation de papules évoque très fortement une syphilis secondaire ?","answer":"Les paumes et les plantes (papules palmo-plantaires)","accept":["palmo-plantaire","palmo-plantaires","palmo plantaire","paumes et plantes","paumes et plantaires"],"keywords":["palm"],"explanation":"Les papules palmo-plantaires sont très évocatrices de syphilis secondaire. Elles sont cuivrées, souvent discrètes : il faut penser à les chercher à l'examen.","src":"p. 192, 200"},{"id":"d162-qroc-209","type":"QROC","rank":"A","objective":"d162-obj-27","tags":["paraclinique","biologie"],"difficulty":1,"question":"Quel test sérologique de la syphilis est réalisé en première intention ?","answer":"Un test tréponémique : l'ELISA","accept":["elisa","test tréponémique","test treponemique","tt"],"keywords":["elisa"],"explanation":"En pratique, on commence par l'ELISA (test tréponémique, TT). Si, et seulement si, il est positif, le biologiste réalise un test non tréponémique (VDRL ou RPR).","src":"p. 194"},{"id":"d162-qroc-210","type":"QROC","rank":"A","objective":"d162-obj-27","tags":["paraclinique","biologie"],"difficulty":2,"question":"Dans quelle condition réalise-t-on un test non tréponémique (VDRL, RPR) ?","answer":"Uniquement si le test tréponémique (ELISA) est positif","accept":["si le tt est positif","si le test tréponémique est positif","si elisa positif","si l'elisa est positif","tt positif"],"keywords":["trépon","positif"],"explanation":"Le TT affirme ou infirme une tréponématose ; le TNT, réalisé seulement si le TT est positif, précise l'évolutivité et sert au suivi.","src":"p. 194, 200"},{"id":"d162-qroc-211","type":"QROC","rank":"A","objective":"d162-obj-27","tags":["paraclinique","pièges"],"difficulty":2,"question":"Quel piège sérologique existe pendant les 7 premiers jours d'un chancre syphilitique ?","answer":"Le TT et le TNT peuvent encore être négatifs","accept":["tt et tnt négatifs","les deux tests négatifs","sérologie négative","tt et tnt peuvent être négatifs","sérologie encore négative"],"keywords":["négatif"],"explanation":"Pendant les 7 premiers jours, les deux tests peuvent être négatifs. Ensuite le TT se positive rapidement (7e au 10e jour) et le TNT 10 à 15 jours après l'apparition du chancre ; au stade secondaire, les deux sont toujours positifs.","src":"p. 194-196"},{"id":"d162-qroc-212","type":"QROC","rank":"A","objective":"d162-obj-27","tags":["paraclinique","pièges"],"difficulty":2,"question":"Citez une cause classique de fausse sérologie syphilitique (VDRL positif, TPHA négatif).","answer":"Lupus ou syndrome des anticorps anti-phospholipides (ou grossesse)","accept":["lupus","sapl","grossesse","anticorps anti-phospholipides","mycoplasma pneumoniae","borréliose"],"keywords":["lupus"],"explanation":"Un TNT positif isolé évoque une fausse sérologie : maladies dysimmunitaires (lupus, SAPL), grossesse, certaines infections (Mycoplasma pneumoniae, borrélioses). Dans 10 % des cas, le TNT se positive toutefois avant le TT.","src":"p. 194, 196"},{"id":"d162-qroc-213","type":"QROC","rank":"A","objective":"d162-obj-28","tags":["suivi","biologie"],"difficulty":2,"question":"Quel critère d'évolution du TNT quantitatif, 6 mois après le traitement, atteste de son efficacité ?","answer":"Titre divisé par 4 (soit 2 dilutions)","accept":["divisé par 4","divise par 4","titre divisé par 4","2 dilutions","baisse de 2 dilutions","division par 4"],"keywords":["divis","4"],"explanation":"La surveillance de l'efficacité repose sur le TNT quantitatif (VDRL) : le titre doit être divisé par 4 à 6 mois. Sans cette décroissance, le traitement doit être repris. Le TT quantitatif n'est pas un bon marqueur de l'évolutivité.","src":"p. 195, 198"},{"id":"d162-qroc-214","type":"QROC","rank":"A","objective":"d162-obj-28","tags":["traitement"],"difficulty":1,"question":"Quel est le traitement de la syphilis précoce (primaire, secondaire, latente précoce) en l'absence d'allergie à la pénicilline ?","answer":"Benzathine-benzylpénicilline 2,4 MU en 1 injection IM unique","accept":["benzathine","benzathine-benzylpénicilline","benzathine benzylpénicilline","extencilline"],"keywords":["benzathine"],"explanation":"Le schéma est identique pour les trois formes précoces : une seule injection IM de 2,4 MU de benzathine-benzylpénicilline. Si le TNT ne baisse pas assez, avis spécialisé et 3 injections à 8 jours d'intervalle.","src":"p. 197-198"},{"id":"d162-qroc-215","type":"QROC","rank":"A","objective":"d162-obj-28","tags":["traitement"],"difficulty":2,"question":"Quel traitement de la syphilis précoce chez un patient allergique à la pénicilline (hors grossesse et infection par le VIH) ?","answer":"Doxycycline 100 mg matin et soir pendant 14 jours","accept":["doxycycline","doxycycline 14 jours","doxycycline 100 mg x2 pendant 14 jours"],"keywords":["doxycycline"],"explanation":"En cas d'allergie : cure de 14 jours de doxycycline (100 mg matin et soir). Chez la femme enceinte et le patient séropositif pour le VIH, on s'oriente vers une induction de tolérance à la pénicilline.","src":"p. 198"},{"id":"d162-qroc-216","type":"QROC","rank":"A","objective":"d162-obj-28","tags":["traitement","pièges"],"difficulty":2,"question":"Quelle réaction bénigne, due à la lyse des tréponèmes, peut survenir quelques heures après l'injection de pénicilline dans la syphilis secondaire ?","answer":"La réaction d'Herxheimer","accept":["herxheimer","réaction d'herxheimer","reaction d herxheimer"],"keywords":["herxheimer"],"explanation":"Fièvre, céphalées, myalgies et accentuation des signes cutanés : elle est toujours bénigne et ne doit pas être prise pour une allergie à la pénicilline. On prescrit un antipyrétique et on prévient le patient.","src":"p. 198"},{"id":"d162-qroc-217","type":"QROC","rank":"A","objective":"d162-obj-04","tags":["suivi","prévention"],"difficulty":2,"question":"Une personne a eu un contact sexuel il y a plus de 6 semaines avec un patient ayant une syphilis certaine. Sa sérologie est négative : que faire ?","answer":"Refaire la sérologie à 3 mois","accept":["refaire à 3 mois","refaire la sérologie à 3 mois","sérologie à 3 mois","contrôle à 3 mois"],"keywords":["3 mois"],"explanation":"Contact de plus de 6 semaines : on fait une sérologie ; si elle est positive on traite, si elle est négative on la refait à 3 mois.","src":"p. 198"},{"id":"d162-qroc-218","type":"QROC","rank":"A","objective":"d162-obj-04","tags":["traitement","prévention"],"difficulty":2,"question":"Quelle conduite pour une personne ayant eu un contact sexuel il y a moins de 6 semaines avec un patient ayant une syphilis certaine ?","answer":"Traiter d'emblée (benzathine-benzylpénicilline 2,4 MU IM) + sérologie","accept":["traiter d'emblée","traiter systématiquement","traitement systématique","traitement d'emblée","benzathine"],"keywords":["trait"],"explanation":"Contact de moins de 6 semaines : on traite systématiquement par une injection de 2,4 MU de benzathine-benzylpénicilline, et une sérologie est prélevée.","src":"p. 198"},{"id":"d162-qroc-219","type":"QROC","rank":"A","objective":"d162-obj-18","tags":["traitement","pièges"],"difficulty":2,"question":"Devant une ulcération génitale, que recommande l'OMS vis-à-vis des résultats des tests sérologiques avant de traiter ?","answer":"Ne pas attendre les résultats du TT et du TNT pour traiter","accept":["ne pas attendre","sans attendre","traiter sans attendre les résultats","ne pas attendre les résultats"],"keywords":["attendre"],"explanation":"Devant une ulcération génitale, il ne faut pas attendre les résultats des tests tréponémique et non tréponémique pour traiter.","src":"p. 197"},{"id":"d162-qroc-220","type":"QROC","rank":"A","objective":"d162-obj-05","tags":["diagnostic","étiologie"],"difficulty":2,"question":"Quelle cause d'ulcération génitale associe terrain africain, fond sale, douleurs vives et adénopathies inflammatoires ?","answer":"Le chancre mou","accept":["chancre mou","le chancre mou"],"keywords":["chancre mou"],"explanation":"À l'inverse du chancre syphilitique (fond propre, indolore, adénopathie non inflammatoire), le chancre mou est douloureux, à fond sale, avec des adénopathies inflammatoires.","src":"p. 188, 190, 197"},{"id":"d162-qroc-221","type":"QROC","rank":"A","objective":"d162-obj-05","tags":["diagnostic","étiologie"],"difficulty":2,"question":"Quelle maladie du diagnostic différentiel d'une ulcération génitale associe anorectite, ulcérations anogénitales et diarrhées trompeuses chez des homosexuels ou des sujets africains ?","answer":"La maladie de Nicolas-Favre (lymphogranulomatose vénérienne, LGV)","accept":["nicolas-favre","nicolas favre","maladie de nicolas-favre","lymphogranulomatose vénérienne","lgv"],"keywords":["nicolas"],"explanation":"C'est la lymphogranulomatose vénérienne, due aux sérotypes L1 à L3 de C. trachomatis. Elle est à distinguer du chancre mou, de la donovanose et de l'herpès.","src":"p. 183, 197"},{"id":"d162-qroc-222","type":"QROC","rank":"A","objective":"d162-obj-23","tags":["grossesse","complications"],"difficulty":2,"question":"À partir de quand le tréponème franchit-il le placenta, ce qui rend la syphilis grave chez la femme enceinte ?","answer":"Après le 4e mois de grossesse (16e semaine d'aménorrhée)","accept":["4e mois","16 sa","16e semaine","4 mois","quatrième mois"],"keywords":["4e mois"],"explanation":"Le passage transplacentaire expose à une atteinte fœtale après le 4e mois de grossesse (environ 16 SA). La sérologie de la syphilis est obligatoire au 1er trimestre de la grossesse.","src":"p. 188, 200"},{"id":"d162-qroc-223","type":"QROC","rank":"B","objective":"d162-obj-25","tags":["complications","diagnostic"],"difficulty":2,"question":"Au cours d'une syphilis secondaire, une uvéite ou l'atteinte d'une paire crânienne (hypoacousie, paralysie faciale) fait évoquer quoi ?","answer":"Une neurosyphilis précoce","accept":["neurosyphilis","neurosyphilis précoce","syphilis neurologique","neuro syphilis"],"keywords":["neurosyphilis"],"explanation":"Les atteintes ophtalmiques et des paires crâniennes sont des neurosyphilis précoces : on fait une ponction lombaire et, quel que soit son résultat, on traite par pénicilline G pendant 14 jours. Les céphalées seules ne signent pas une atteinte neuroméningée.","src":"p. 193"},{"id":"d162-qroc-224","type":"QROC","rank":"B","objective":"d162-obj-26","tags":["clinique"],"difficulty":1,"question":"Quelle est la première éruption de la syphilis secondaire (macules rose pâle du tronc, souvent inaperçue, spontanément résolutive en 7 à 10 jours) ?","answer":"La roséole syphilitique","accept":["roséole","roséole syphilitique","roseole","roseole syphilitique"],"keywords":["roséole"],"explanation":"La roséole survient dans les 6 semaines après le chancre. Elle ne doit pas être confondue avec une éruption virale (une primo-infection VIH doit être éliminée) ou une toxidermie.","src":"p. 190, 197, 200"},{"id":"d162-qroc-225","type":"QROC","rank":"B","objective":"d162-obj-30","tags":["étiologie","épidémiologie"],"difficulty":1,"question":"Quels sont les deux types d'HPV à haut risque oncogène les plus fréquents ?","answer":"HPV 16 et 18","accept":["16 et 18","hpv 16 et 18","hpv16 et 18","16, 18","hpv 16 18"],"keywords":["16","18"],"explanation":"Les HPV à haut risque oncogène (principalement 16 et 18) sont responsables des lésions précancéreuses puis cancéreuses.","src":"p. 201"},{"id":"d162-qroc-226","type":"QROC","rank":"B","objective":"d162-obj-30","tags":["étiologie","épidémiologie"],"difficulty":1,"question":"Quels HPV à bas risque sont responsables d'environ 90 % des condylomes ?","answer":"HPV 6 et 11","accept":["6 et 11","hpv 6 et 11","hpv6 et 11","6, 11"],"keywords":["6","11"],"explanation":"Les HPV 6 et 11, à bas risque, causent près de 90 % des verrues génitales. Lors d'une infection, on peut être infecté à la fois par des types non oncogènes et oncogènes.","src":"p. 201"},{"id":"d162-qroc-227","type":"QROC","rank":"A","objective":"d162-obj-37","tags":["clinique"],"difficulty":1,"question":"Quel terme imagé désigne l'aspect classique des condylomes acuminés ?","answer":"Les « crêtes-de-coq »","accept":["crêtes-de-coq","crête de coq","crêtes de coq","crete de coq"],"keywords":["coq"],"explanation":"Les condylomes acuminés sont des excroissances charnues couvertes de petites verrucosités kératosiques (0,2 à 1 cm), en nombre variable. Les condylomes plans, eux, sont des maculo-papules rosées parfois à peine visibles.","src":"p. 201"},{"id":"d162-qroc-228","type":"QROC","rank":"A","objective":"d162-obj-30","tags":["diagnostic","clinique"],"difficulty":2,"question":"Quel produit appliqué sur la peau ou la muqueuse permet de mieux visualiser les condylomes plans ?","answer":"L'acide acétique (à 5 %)","accept":["acide acétique","acide acetique","acide acétique à 5 %","acide acétique 5 %"],"keywords":["acétique"],"explanation":"L'application d'acide acétique à 5 % suivie d'un examen à la loupe est le principe de la colposcopie ; le lugol peut aussi servir à diriger la biopsie sur une zone suspecte.","src":"p. 201-202"},{"id":"d162-qroc-229","type":"QROC","rank":"A","objective":"d162-obj-30","tags":["diagnostic","prévention"],"difficulty":1,"question":"Devant des verrues anogénitales, que faut-il systématiquement rechercher ?","answer":"Une autre IST associée","accept":["autre ist","ist associée","une autre ist","autre ist associée","ist associee"],"keywords":["ist"],"explanation":"Une autre IST est associée en moyenne dans 25 % des cas : sérologie VIH, test tréponémique, sérologie de l'hépatite B, PCR Chlamydia et gonocoque. Il faut aussi examiner le partenaire.","src":"p. 205-206"},{"id":"d162-qroc-230","type":"QROC","rank":"A","objective":"d162-obj-19","tags":["diagnostic","prévention"],"difficulty":1,"question":"À partir de quel âge le test HPV-HR (PCR) est-il recommandé en première intention pour le dépistage chez la femme ?","answer":"À partir de 30 ans","accept":["30 ans","à partir de 30 ans","après 30 ans","plus de 30 ans"],"keywords":["30"],"explanation":"Avant 30 ans, la clairance spontanée des HPV est incomplète : le test serait presque toujours positif sans qu'il existe de pathologie sous-jacente.","src":"p. 202"},{"id":"d162-qroc-231","type":"QROC","rank":"A","objective":"d162-obj-19","tags":["prévention","suivi"],"difficulty":1,"question":"Quelle est la périodicité du frottis cervico-vaginal de dépistage des néoplasies intra-épithéliales cervicales ?","answer":"Tous les 3 ans (ou test HPV-HR)","accept":["tous les 3 ans","3 ans","tous les trois ans","trois ans"],"keywords":["3 ans"],"explanation":"Le dépistage systématique repose sur un frottis tous les 3 ans ou un test HPV-HR. En cas de dysplasie, même mineure, on réalise une colposcopie et, si besoin, une biopsie dirigée.","src":"p. 205"},{"id":"d162-qroc-232","type":"QROC","rank":"A","objective":"d162-obj-22","tags":["prévention"],"difficulty":1,"question":"À quel âge propose-t-on la vaccination anti-HPV à tous les adolescents (filles et garçons) ?","answer":"Entre 11 et 14 ans (rattrapage de 15 à 19 ans révolus)","accept":["11 à 14 ans","11-14 ans","entre 11 et 14 ans","11 et 14 ans"],"keywords":["11","14"],"explanation":"La vaccination est proposée entre 11 et 14 ans, avec rattrapage de 15 à 19 ans révolus, de préférence avant toute contamination. Toute nouvelle vaccination débute par le vaccin nonavalent (Gardasil 9) ; chez les HSH, elle est recommandée jusqu'à 26 ans.","src":"p. 204"},{"id":"d162-qroc-233","type":"QROC","rank":"A","objective":"d162-obj-22","tags":["prévention"],"difficulty":2,"question":"Quel est le schéma du vaccin nonavalent anti-HPV chez un jeune de 15 à 19 ans révolus ?","answer":"3 doses selon un schéma 0, 2 et 6 mois","accept":["3 doses","0, 2 et 6 mois","0-2-6 mois","trois doses","0 2 6 mois"],"keywords":["3 doses"],"explanation":"De 15 à 19 ans révolus (et chez les HSH jusqu'à 26 ans) : 3 doses à 0, 2 et 6 mois. De 11 à 14 ans révolus : 2 doses espacées de 6 à 13 mois.","src":"p. 204-205"},{"id":"d162-qroc-234","type":"QROC","rank":"A","objective":"d162-obj-12","tags":["étiologie"],"difficulty":2,"question":"Parmi la candidose, la vaginose bactérienne et la trichomonose, laquelle est considérée comme une IST ?","answer":"La trichomonose (Trichomonas vaginalis)","accept":["trichomonose","trichomonas vaginalis","trichomonas","la trichomonose"],"keywords":["trichomon"],"explanation":"Trichomonas vaginalis, protozoaire flagellé anaérobie dont le réservoir est le tractus urogénital, est considéré comme une IST, contrairement à la candidose et à la vaginose bactérienne.","src":"p. 206"},{"id":"d162-qroc-235","type":"QROC","rank":"B","objective":"d162-obj-34","tags":["traitement"],"difficulty":2,"question":"Citez un traitement oral de la trichomonose (une dose unique de 2 g est possible).","answer":"Métronidazole 2 g en dose unique (ou secnidazole 2 g)","accept":["métronidazole","metronidazole","secnidazole","métronidazole 2 g"],"keywords":["nidazole"],"explanation":"Au choix : métronidazole (2 g en dose unique, ou 500 mg deux fois par jour pendant 7 jours) ou secnidazole 2 g en dose unique. Le(s) partenaire(s) doivent être traités simultanément.","src":"p. 207-208"},{"id":"d162-qroc-236","type":"QROC","rank":"B","objective":"d162-obj-33","tags":["paraclinique","diagnostic"],"difficulty":2,"question":"Comment pose-t-on le diagnostic direct d'une trichomonose (prélèvement vaginal ou urétral) ?","answer":"Examen direct à l'état frais (parasite mobile) ou PCR","accept":["examen direct à l'état frais","état frais","examen direct","pcr"],"keywords":["frais"],"explanation":"On dépose une goutte de sécrétion entre lame et lamelle : le parasite est mobile. Chez la femme, le recueil se fait dans le cul-de-sac vaginal postérieur ; chez l'homme, sur l'écoulement urétral ou le 1er jet urinaire.","src":"p. 207"},{"id":"d162-qroc-701","type":"QROC","rank":"A","objective":"d162-obj-01","tags":["étiologie","clinique"],"difficulty":1,"question":"Quels sont les principaux sites d'infection du gonocoque chez l'homme et chez la femme ?","answer":"Urètre (homme) ; col et vagin (femme)","accept":["urètre chez l'homme, col chez la femme","urètre et col"],"keywords":["uret","col"],"explanation":"Chez l'homme le gonocoque infecte l'urètre, où le portage asymptomatique est exceptionnel. Chez la femme il infecte le col et le vagin.","src":"p. 180"},{"id":"d162-qroc-702","type":"QROC","rank":"A","objective":"d162-obj-01","tags":["épidémiologie","clinique"],"difficulty":2,"question":"Quelles pratiques sexuelles imposent de rechercher systématiquement un portage pharyngé de gonocoque, le plus souvent asymptomatique ?","answer":"Rapports orogénitaux réceptifs non protégés (partenaires multiples)","accept":["rapports orogénitaux","rapports oro-génitaux","fellation","rapports oraux"],"keywords":["oro"],"explanation":"Le portage pharyngé est fréquent et souvent muet chez les homo- ou bisexuels ; il faut le chercher devant une conduite à risque (partenaires multiples, rapports orogénitaux réceptifs non protégés).","src":"p. 180"},{"id":"d162-qroc-703","type":"QROC","rank":"A","objective":"d162-obj-08","tags":["clinique"],"difficulty":1,"question":"Quelle est la manifestation la plus fréquente de la gonococcie non compliquée chez l'homme ?","answer":"L'urétrite antérieure aiguë","accept":["urétrite antérieure aiguë","urétrite aiguë","urétrite"],"keywords":["uretrite"],"explanation":"L'urétrite antérieure aiguë est la manifestation la plus fréquente : écoulement purulent, dysurie, brûlures urétrales, prurit. Le tableau est le plus souvent bruyant mais peut être asymptomatique.","src":"p. 180"},{"id":"d162-qroc-704","type":"QROC","rank":"A","objective":"d162-obj-08","tags":["clinique"],"difficulty":2,"question":"Quelles atteintes de l'orifice urétral et du gland peuvent accompagner une urétrite gonococcique ?","answer":"Méatite, voire balanite","accept":["méatite","balanite"],"keywords":["meatite"],"explanation":"À côté de l'écoulement, de la dysurie et des brûlures, l'inflammation du méat (méatite) voire du gland (balanite) est possible.","src":"p. 180"},{"id":"d162-qroc-705","type":"QROC","rank":"A","objective":"d162-obj-08","tags":["clinique"],"difficulty":2,"question":"Quelle proportion des anorectites gonococciques est asymptomatique ?","answer":"Les deux tiers (2/3)","accept":["2/3","deux tiers","les deux tiers"],"keywords":["tiers"],"explanation":"L'anorectite gonococcique est asymptomatique dans 2 cas sur 3 ; quand elle est symptomatique : prurit anal, anite, écoulement rectal purulent, saignements, diarrhée.","src":"p. 180"},{"id":"d162-qroc-706","type":"QROC","rank":"A","objective":"d162-obj-08","tags":["clinique"],"difficulty":2,"question":"Quels signes composent le syndrome rectal d'une anorectite gonococcique symptomatique ?","answer":"Ténesme, épreintes, diarrhée mucopurulente","accept":["ténesme","épreintes","diarrhée mucopurulente","sensation de défécation incomplète"],"keywords":["tenesme"],"explanation":"Le syndrome rectal associe ténesme, épreintes et diarrhée mucopurulente, parfois avec une sensation de défécation incomplète.","src":"p. 180"},{"id":"d162-qroc-707","type":"QROC","rank":"A","objective":"d162-obj-08","tags":["clinique","physiopathologie"],"difficulty":2,"question":"Pourquoi une oropharyngite gonococcique traitée peut-elle persister et entretenir la chaîne de contamination ?","answer":"Mauvaise diffusion des antibiotiques à ce niveau","accept":["mauvaise diffusion des antibiotiques","mauvaise diffusion","diffusion insuffisante"],"keywords":["diffusion"],"explanation":"L'oropharyngite est le plus souvent asymptomatique ; comme les antibiotiques diffusent mal dans cette localisation, le portage persiste après traitement et le patient reste contaminant.","src":"p. 180"},{"id":"d162-qroc-708","type":"QROC","rank":"A","objective":"d162-obj-10","tags":["clinique"],"difficulty":2,"question":"Citez un signe fonctionnel d'une cervicite gonococcique symptomatique chez la femme.","answer":"Leucorrhées purulentes ou pesanteur pelvienne","accept":["leucorrhées purulentes","pesanteur pelvienne","signes d'urétrite"],"keywords":["leucorrh","pesanteur"],"explanation":"La cervicite est la manifestation la plus fréquente chez la femme ; elle donne des leucorrhées purulentes, une pesanteur pelvienne, parfois des signes d'urétrite. Mais 70 % des infections non compliquées sont asymptomatiques.","src":"p. 180-181"},{"id":"d162-qroc-709","type":"QROC","rank":"B","objective":"d162-obj-02","tags":["épidémiologie"],"difficulty":2,"question":"Dans quel sexe et dans quelle région de France l'incidence de la gonococcie est-elle la plus élevée ?","answer":"Chez les hommes ; en Île-de-France","accept":["hommes et île-de-france","hommes, île-de-france"],"keywords":["homme","france"],"explanation":"L'incidence de la gonococcie augmente ; elle est plus élevée chez les hommes que chez les femmes et plus élevée en Île-de-France qu'ailleurs en métropole.","src":"p. 180"},{"id":"d162-qroc-710","type":"QROC","rank":"B","objective":"d162-obj-20","tags":["épidémiologie","physiopathologie"],"difficulty":2,"question":"Quel mécanisme explique la résistance du gonocoque à la pénicilline (15 % des souches) ?","answer":"La production de β-lactamase","accept":["lactamase","bêta-lactamase","production de lactamase"],"keywords":["lactamase"],"explanation":"15 % des souches produisent une β-lactamase ; les résistances touchent aussi les cyclines (20 %) et la ciprofloxacine (40 %).","src":"p. 180"},{"id":"d162-qroc-711","type":"QROC","rank":"B","objective":"d162-obj-20","tags":["épidémiologie"],"difficulty":2,"question":"Quelle est la fréquence de la résistance du gonocoque à la ciprofloxacine ?","answer":"40 % des souches","accept":["40 %","40"],"keywords":["40"],"explanation":"La résistance à la ciprofloxacine (40 %) dépasse celle aux cyclines (20 %) et à la pénicilline (15 %) : c'est pourquoi les quinolones ne sont proposées qu'après antibiogramme.","src":"p. 180"},{"id":"d162-qroc-712","type":"QROC","rank":"B","objective":"d162-obj-20","tags":["épidémiologie"],"difficulty":2,"question":"Quelle évolution préoccupante de la sensibilité du gonocoque aux céphalosporines de 3e génération est observée ?","answer":"Augmentation des CMI, avec résistances vraies ponctuelles","accept":["augmentation des cmi","cmi augmentées","hausse des cmi"],"keywords":["cmi"],"explanation":"Les CMI des céphalosporines de 3e génération augmentent et de rares résistances vraies sont observées : d'où la nécessité de réactualiser régulièrement les schémas.","src":"p. 180"},{"id":"d162-qroc-713","type":"QROC","rank":"B","objective":"d162-obj-15","tags":["paraclinique"],"difficulty":2,"question":"Chez un homme avec écoulement urétral spontané, sur quoi réalise-t-on le prélèvement bactériologique ?","answer":"Sur l'écoulement urétral","accept":["écoulement urétral","sur l'écoulement"],"keywords":["ecoulement"],"explanation":"En cas d'écoulement spontané, c'est le prélèvement de choix chez le patient symptomatique.","src":"p. 181"},{"id":"d162-qroc-714","type":"QROC","rank":"A","objective":"d162-obj-15","tags":["paraclinique"],"difficulty":2,"question":"Chez un homme symptomatique sans écoulement urétral, quel prélèvement bactériologique est préférable ?","answer":"1er jet d'urine, ≥ 2 h après la dernière miction","accept":["1er jet d'urine","premier jet d'urine","1er jet urinaire","premier jet"],"keywords":["jet"],"explanation":"En l'absence d'écoulement, on prélève au mieux un 1er jet d'urine (au moins 2 heures après la dernière miction), sinon un prélèvement endo-urétral.","src":"p. 181"},{"id":"d162-qroc-715","type":"QROC","rank":"B","objective":"d162-obj-15","tags":["paraclinique"],"difficulty":2,"question":"Quels sont les seuils de polynucléaires neutrophiles définissant l'urétrite « biologique » au frottis urétral (grossissement 100 puis 400) ?","answer":"> 5 PNN (×100) ou > 10 PNN (×400)","accept":["5 et 10","5 pnn ou 10 pnn","plus de 5 et plus de 10"],"keywords":["5","10"],"explanation":"L'urétrite biologique est définie par plus de 5 PNN au grossissement 100 ou plus de 10 PNN au grossissement 400.","src":"p. 181"},{"id":"d162-qroc-716","type":"QROC","rank":"B","objective":"d162-obj-15","tags":["paraclinique"],"difficulty":2,"question":"Quelle expression imagée décrit l'aspect des diplocoques du gonocoque à l'examen direct ?","answer":"Diplocoques « en grains de café »","accept":["grains de café","grain de café","en grains de café"],"keywords":["cafe"],"explanation":"À l'examen direct (Gram ou bleu de méthylène), les diplocoques à Gram négatif sont intracellulaires, en « grains de café ».","src":"p. 181"},{"id":"d162-qroc-717","type":"QROC","rank":"B","objective":"d162-obj-15","tags":["paraclinique"],"difficulty":3,"question":"Quelle est la sensibilité de l'examen direct dans l'urétrite masculine symptomatique à gonocoque ?","answer":"Sensibilité et spécificité > 95 %","accept":["> 95","95 %","95"],"keywords":["95"],"explanation":"Dans l'urétrite masculine symptomatique, l'examen direct a une sensibilité et une spécificité > 95 % ; elles sont moins bonnes aux autres sites et chez la femme.","src":"p. 181"},{"id":"d162-qroc-718","type":"QROC","rank":"B","objective":"d162-obj-15","tags":["paraclinique","pièges"],"difficulty":2,"question":"Pourquoi l'identification de diplocoques extracellulaires ne suffit-elle pas à affirmer une gonococcie ?","answer":"Il existe des Neisseria non pathogènes","accept":["neisseria non pathogènes","neisseria non pathogenes","autres neisseria"],"keywords":["pathog"],"explanation":"Seule la forme intracellulaire est évocatrice ; une forme extracellulaire peut correspondre à des Neisseria non pathogènes, d'où la culture systématique.","src":"p. 181"},{"id":"d162-qroc-719","type":"QROC","rank":"B","objective":"d162-obj-15","tags":["paraclinique"],"difficulty":2,"question":"Sur quel milieu la culture du gonocoque est-elle réalisée systématiquement ?","answer":"Gélose au sang cuit (gélose chocolat)","accept":["gélose chocolat","chocolat","sang cuit","gélose au sang cuit"],"keywords":["chocolat"],"explanation":"La culture sur gélose au sang cuit (« gélose chocolat ») est systématique : elle confirme le diagnostic et fournit un antibiogramme en 24 à 48 h.","src":"p. 182"},{"id":"d162-qroc-720","type":"QROC","rank":"B","objective":"d162-obj-15","tags":["paraclinique"],"difficulty":2,"question":"Quel avantage de la culture du gonocoque, au-delà de la confirmation diagnostique, justifie qu'elle reste systématique ?","answer":"Elle donne un antibiogramme en 24-48 h (suivi des résistances)","accept":["antibiogramme","antibiogramme en 24 à 48 heures"],"keywords":["antibiogramme"],"explanation":"L'antibiogramme obtenu en 24 à 48 h est utile pour surveiller les résistances, d'autant que les souches deviennent moins sensibles aux antibiotiques.","src":"p. 182"},{"id":"d162-qroc-721","type":"QROC","rank":"B","objective":"d162-obj-15","tags":["paraclinique"],"difficulty":3,"question":"À l'oropharynx, à l'anus et au col, la PCR est plus sensible que la culture : quel est son inconvénient ?","answer":"Elle ne permet pas de tester la sensibilité de la souche","accept":["pas d'antibiogramme","pas de test de sensibilité","ne donne pas d'antibiogramme","sensibilité de la souche"],"keywords":["sensibilite"],"explanation":"La culture est moins sensible à ces sites, d'où l'intérêt de la PCR ; en revanche, la PCR ne donne pas l'antibiogramme.","src":"p. 182"},{"id":"d162-qroc-722","type":"QROC","rank":"A","objective":"d162-obj-18","tags":["traitement"],"difficulty":1,"question":"Quel type de traitement, délivré sur le lieu même de la consultation, est recommandé dans la gonococcie ?","answer":"Le traitement minute (dose unique)","accept":["traitement minute","dose unique","minute"],"keywords":["minute"],"explanation":"On privilégie un traitement minute en dose unique, donné sur place, pour traiter immédiatement le patient.","src":"p. 182"},{"id":"d162-qroc-723","type":"QROC","rank":"A","objective":"d162-obj-18","tags":["traitement"],"difficulty":2,"question":"Quelle particularité du traitement d'une urétrite gonococcique faut-il connaître chez un patient infecté par le VIH ?","answer":"Aucune : le traitement est identique","accept":["identique","le même traitement","aucune"],"keywords":["identique"],"explanation":"Le traitement des urétrites est identique en cas d'infection par le VIH.","src":"p. 182"},{"id":"d162-qroc-724","type":"QROC","rank":"A","objective":"d162-obj-04","tags":["prévention","pièges"],"difficulty":1,"question":"Quel risque faut-il souligner (par l'éducation du patient) après le traitement d'une IST ?","answer":"Le risque de recontamination","accept":["recontamination","réinfection","recontaminer"],"keywords":["recontam"],"explanation":"Pour toute IST, on identifie les partenaires, on propose un dépistage, on insiste sur le risque de recontamination et on éduque le patient.","src":"p. 182"},{"id":"d162-qroc-725","type":"QROC","rank":"B","objective":"d162-obj-34","tags":["traitement"],"difficulty":2,"question":"Dans quelle situation donne-t-on la ceftriaxone par voie IV plutôt qu'IM dans une gonococcie non compliquée ?","answer":"En cas d'anomalie de l'hémostase","accept":["anomalie de l'hémostase","trouble de l'hémostase","troubles de la coagulation","hémostase"],"keywords":["hemostase"],"explanation":"La ceftriaxone 1000 mg se donne en IM unique, ou en IV si le patient a une anomalie de l'hémostase (risque lié à l'injection intramusculaire).","src":"p. 182"},{"id":"d162-qroc-726","type":"QROC","rank":"B","objective":"d162-obj-20","tags":["traitement"],"difficulty":2,"question":"Citez un antibiotique de remplacement de la ceftriaxone, en dose unique, en cas d'allergie aux β-lactamines dans une gonococcie non compliquée.","answer":"Azithromycine, gentamycine ou ciprofloxacine","accept":["azithromycine","gentamycine","gentamicine","ciprofloxacine"],"keywords":["azithromycine","gentamycine","ciprofloxacine"],"explanation":"Trois alternatives en dose unique : azithromycine 2 g PO, gentamycine 240 mg IM, ciprofloxacine 500 mg PO (cette dernière seulement avec antibiogramme).","src":"p. 182"},{"id":"d162-qroc-727","type":"QROC","rank":"B","objective":"d162-obj-34","tags":["traitement","pièges"],"difficulty":2,"question":"Quelle dose d'azithromycine en prise unique traite un gonocoque chez un patient allergique aux β-lactamines ?","answer":"2 g par voie orale","accept":["2 g","2g","2000 mg","2 grammes"],"keywords":["2 g"],"explanation":"Contre le gonocoque (allergie aux β-lactamines) l'azithromycine est donnée à 2 g en dose unique ; contre Chlamydia, la dose unique est de 1 g.","src":"p. 182"},{"id":"d162-qroc-728","type":"QROC","rank":"B","objective":"d162-obj-34","tags":["traitement","grossesse"],"difficulty":3,"question":"Quelles trois classes d'antibiotiques sont contre-indiquées chez la femme enceinte atteinte de gonococcie ?","answer":"Quinolones, cyclines, aminosides","accept":["quinolones, cyclines, aminosides","quinolones cyclines aminosides"],"keywords":["quinolone","cycline","aminoside"],"explanation":"Chez la femme enceinte on évite quinolones, cyclines et aminosides ; on utilise la ceftriaxone IM ou le céfixime oral.","src":"p. 182"},{"id":"d162-qroc-729","type":"QROC","rank":"B","objective":"d162-obj-34","tags":["traitement","grossesse"],"difficulty":2,"question":"Quelle dose de céfixime en prise orale unique traite la gonococcie non compliquée de la femme enceinte ?","answer":"400 mg","accept":["400 mg","400"],"keywords":["400"],"explanation":"Chez la femme enceinte : ceftriaxone 1000 mg IM unique ou céfixime 400 mg per os en prise unique.","src":"p. 182"},{"id":"d162-qroc-730","type":"QROC","rank":"B","objective":"d162-obj-34","tags":["traitement"],"difficulty":2,"question":"Quelle dose de céfixime en prise orale unique peut remplacer la ceftriaxone dans une orchiépididymite gonococcique ?","answer":"800 mg","accept":["800 mg","800"],"keywords":["800"],"explanation":"L'orchiépididymite se traite par ceftriaxone 1000 mg IM unique ou céfixime 800 mg per os unique (400 mg chez la femme enceinte).","src":"p. 182"},{"id":"d162-qroc-731","type":"QROC","rank":"B","objective":"d162-obj-34","tags":["traitement"],"difficulty":2,"question":"À l'oropharynx, quel antibiotique est préconisé dans la gonococcie quand un antibiogramme est impossible ?","answer":"La ceftriaxone 1000 mg","accept":["ceftriaxone","ceftriaxone 1000 mg","ceftriaxone 1 g"],"keywords":["ceftriaxone"],"explanation":"Les antibiotiques diffusent mal à l'oropharynx : en l'absence d'antibiogramme on garde la ceftriaxone 1000 mg.","src":"p. 182"},{"id":"d162-qroc-732","type":"QROC","rank":"B","objective":"d162-obj-21","tags":["traitement","complications"],"difficulty":2,"question":"Quelle est la prise en charge d'une septicémie gonococcique ?","answer":"Hospitalisation + ceftriaxone 1 g/j IV, 7 à 10 jours","accept":["hospitalisation et ceftriaxone","ceftriaxone iv 7 à 10 jours"],"keywords":["hospital","ceftriaxone"],"explanation":"La septicémie gonococcique impose l'hospitalisation et la ceftriaxone IV 1 g/jour pendant 7 à 10 jours.","src":"p. 182"},{"id":"d162-qroc-733","type":"QROC","rank":"B","objective":"d162-obj-21","tags":["traitement","complications"],"difficulty":2,"question":"Quelle est la durée de la ceftriaxone IV (1 à 2 g/jour) dans une méningite gonococcique ?","answer":"10 à 14 jours","accept":["10 à 14 jours","10-14 jours","10 à 14"],"keywords":["10","14"],"explanation":"Méningite : ceftriaxone IV 1 à 2 g/jour pendant 10 à 14 jours, avec hospitalisation.","src":"p. 182-183"},{"id":"d162-qroc-734","type":"QROC","rank":"B","objective":"d162-obj-21","tags":["traitement","complications"],"difficulty":2,"question":"Quelle est la durée de la ceftriaxone IV (1 à 2 g/jour) dans une endocardite gonococcique ?","answer":"4 semaines","accept":["4 semaines","quatre semaines","un mois"],"keywords":["4 semaines"],"explanation":"Endocardite : hospitalisation et ceftriaxone IV 1 à 2 g/jour pendant 4 semaines (10 à 14 jours seulement pour une méningite).","src":"p. 182-183"},{"id":"d162-qroc-735","type":"QROC","rank":"B","objective":"d162-obj-21","tags":["traitement"],"difficulty":2,"question":"Quel traitement antibiotique de l'endométrite ou de la salpingite gonococcique (dose, voie, durée) ?","answer":"Ceftriaxone 1 g/jour IV pendant 14 jours","accept":["ceftriaxone 1 g par jour 14 jours","ceftriaxone iv 14 jours"],"keywords":["ceftriaxone","14"],"explanation":"L'infection génitale haute gonococcique est traitée par ceftriaxone 1 g/jour IV pendant 14 jours.","src":"p. 183"},{"id":"d162-qroc-736","type":"QROC","rank":"B","objective":"d162-obj-16","tags":["suivi"],"difficulty":1,"question":"À quel moment réalise-t-on le contrôle clinique systématique après le traitement d'une gonococcie ?","answer":"À J7","accept":["j7","7 jours","jour 7","à 7 jours"],"keywords":["j7"],"explanation":"Un contrôle clinique à J7 est systématique ; un contrôle bactériologique n'est demandé que dans certaines situations.","src":"p. 183"},{"id":"d162-qroc-737","type":"QROC","rank":"B","objective":"d162-obj-16","tags":["suivi"],"difficulty":2,"question":"Quels sont les objectifs du contrôle clinique de J7 après un traitement de gonococcie ?","answer":"Tolérance et efficacité, adapter au résultat bactério, informer","accept":["tolérance et efficacité","évaluer la tolérance","adapter le traitement"],"keywords":["tolerance","efficacite"],"explanation":"On évalue tolérance et efficacité, on adapte le traitement aux résultats bactériologiques et on communique les résultats au patient.","src":"p. 183"},{"id":"d162-qroc-738","type":"QROC","rank":"B","objective":"d162-obj-16","tags":["suivi"],"difficulty":2,"question":"Dans quel cas un contrôle bactériologique à J7 est-il indiqué après traitement d'une gonococcie ?","answer":"Persistance de signes cliniques","accept":["persistance de signes cliniques","signes cliniques persistants","persistance des signes"],"keywords":["persist"],"explanation":"En cas de signes cliniques persistants, on recherche d'autres micro-organismes par PCR.","src":"p. 183"},{"id":"d162-qroc-739","type":"QROC","rank":"B","objective":"d162-obj-16","tags":["suivi"],"difficulty":2,"question":"Quand propose-t-on un contrôle de la PCR dans les formes asymptomatiques de gonococcie ?","answer":"15 jours après le traitement","accept":["15 jours","quinze jours","2 semaines"],"keywords":["15"],"explanation":"Dans les formes asymptomatiques, on propose un contrôle par PCR 15 jours après le traitement.","src":"p. 183"},{"id":"d162-qroc-740","type":"QROC","rank":"A","objective":"d162-obj-09","tags":["définition","étiologie"],"difficulty":1,"question":"Quelle est la nature bactériologique de Chlamydia trachomatis (Gram, mode de vie, mobilité) ?","answer":"Bacille à Gram négatif, intracellulaire obligatoire, immobile","accept":["bacille à gram négatif intracellulaire","bacille gram négatif intracellulaire obligatoire"],"keywords":["bacille","intracellul"],"explanation":"C. trachomatis est un bacille à Gram négatif, intracellulaire obligatoire et immobile.","src":"p. 183"},{"id":"d162-qroc-741","type":"QROC","rank":"A","objective":"d162-obj-09","tags":["étiologie"],"difficulty":1,"question":"Quels sérotypes de C. trachomatis sont responsables des infections urogénitales courantes ?","answer":"Les sérotypes D à K","accept":["d à k","d-k","sérotypes d à k"],"keywords":["d a k"],"explanation":"Les sérotypes D à K donnent les infections urogénitales ; les sérotypes L1, L2 et L3 donnent la lymphogranulomatose vénérienne.","src":"p. 183"},{"id":"d162-qroc-742","type":"QROC","rank":"B","objective":"d162-obj-09","tags":["étiologie"],"difficulty":2,"question":"Quelle maladie est due aux sérotypes L1, L2 et L3 de Chlamydia trachomatis ?","answer":"La lymphogranulomatose vénérienne (maladie de Nicolas-Favre)","accept":["lymphogranulomatose vénérienne","lgv","maladie de nicolas-favre","nicolas-favre"],"keywords":["lymphogranulomatose"],"explanation":"Les sérotypes L1-L3 sont responsables de la LGV ou maladie de Nicolas-Favre, qui fait partie du diagnostic différentiel des ulcérations génitales.","src":"p. 183"},{"id":"d162-qroc-743","type":"QROC","rank":"B","objective":"d162-obj-02","tags":["épidémiologie"],"difficulty":2,"question":"Quelle bactérie est la première cause d'IST bactérienne dans les pays industrialisés et la première cause identifiée d'urétrite aiguë (devant le gonocoque) ?","answer":"Chlamydia trachomatis","accept":["chlamydia","c. trachomatis","chlamydia trachomatis"],"keywords":["chlamydia"],"explanation":"La chlamydiose est 50 fois plus fréquente que la gonococcie ; sa prévalence est estimée jusqu'à 10 %.","src":"p. 183"},{"id":"d162-qroc-744","type":"QROC","rank":"B","objective":"d162-obj-02","tags":["épidémiologie"],"difficulty":2,"question":"Combien de fois la chlamydiose est-elle plus fréquente que la gonococcie ?","answer":"50 fois","accept":["50 fois","50"],"keywords":["50"],"explanation":"La chlamydiose est environ 50 fois plus fréquente que la gonococcie, mais souvent silencieuse.","src":"p. 183"},{"id":"d162-qroc-745","type":"QROC","rank":"B","objective":"d162-obj-02","tags":["épidémiologie"],"difficulty":2,"question":"Quels sont les pics d'incidence de la chlamydiose chez la femme et chez l'homme ?","answer":"Femme : 15-34 ans ; homme : 20-39 ans","accept":["15 à 34 ans et 20 à 39 ans","15-34 et 20-39"],"keywords":["15","34","39"],"explanation":"Le pic d'incidence se situe entre 15 et 34 ans chez la femme et entre 20 et 39 ans chez l'homme.","src":"p. 183"},{"id":"d162-qroc-746","type":"QROC","rank":"B","objective":"d162-obj-02","tags":["épidémiologie","prévention"],"difficulty":2,"question":"Chez quelles femmes enceintes le dépistage opportuniste de C. trachomatis est-il recommandé, sans limite d'âge ?","answer":"Celles consultant pour une IVG","accept":["ivg","interruption volontaire de grossesse"],"keywords":["ivg"],"explanation":"Dépistage opportuniste ciblé : hommes à facteurs de risque (tout âge), femmes de plus de 25 ans à facteurs de risque, et femmes enceintes consultant pour une IVG, sans limite d'âge.","src":"p. 183"},{"id":"d162-qroc-747","type":"QROC","rank":"B","objective":"d162-obj-02","tags":["épidémiologie","complications"],"difficulty":2,"question":"Quelle proportion des salpingites de la femme jeune est due à C. trachomatis ?","answer":"50 %","accept":["50 %","50","la moitié"],"keywords":["50"],"explanation":"C. trachomatis est responsable de 50 % des salpingites de la femme jeune (et de 70 % des stérilités tubaires).","src":"p. 183"},{"id":"d162-qroc-748","type":"QROC","rank":"B","objective":"d162-obj-02","tags":["épidémiologie"],"difficulty":2,"question":"Depuis 2003, chez quelle population observe-t-on une résurgence de la lymphogranulomatose vénérienne ?","answer":"Homosexuels masculins, souvent infectés par le VIH","accept":["homosexuels masculins","hsh","homosexuels"],"keywords":["homosex"],"explanation":"La LGV a refait surface depuis 2003 chez les homosexuels de sexe masculin, avec une forte proportion de patients infectés par le VIH.","src":"p. 183"},{"id":"d162-qroc-749","type":"QROC","rank":"A","objective":"d162-obj-08","tags":["clinique"],"difficulty":1,"question":"Quelle est la durée d'incubation d'une chlamydiose génitale ?","answer":"Variable : de quelques jours à quelques mois","accept":["quelques jours à quelques mois","variable"],"keywords":["mois"],"explanation":"Contrairement au gonocoque (2 à 7 jours), l'incubation de Chlamydia est variable, de quelques jours à quelques mois ; le tableau est souvent moins bruyant.","src":"p. 184"},{"id":"d162-qroc-750","type":"QROC","rank":"A","objective":"d162-obj-08","tags":["clinique"],"difficulty":1,"question":"Quelle est la manifestation la plus fréquente de la chlamydiose génitale chez l'homme ?","answer":"L'urétrite","accept":["urétrite","l'urétrite","urétrite antérieure"],"keywords":["uretrite"],"explanation":"L'urétrite est la manifestation la plus fréquente ; pharyngites et anorectites sont possibles mais rarement symptomatiques.","src":"p. 184"},{"id":"d162-qroc-751","type":"QROC","rank":"A","objective":"d162-obj-10","tags":["clinique"],"difficulty":2,"question":"Quels signes à l'examen au spéculum évoquent une cervicite à Chlamydia trachomatis ?","answer":"Col fragile, sécrétions mucopurulentes, ectropion friable et hémorragique","accept":["col fragile","fragilité du col","ectropion friable","sécrétions mucopurulentes","ectropion hémorragique"],"keywords":["col","ectropion"],"explanation":"À l'examen : fragilité du col, sécrétions mucopurulentes et/ou ectropion friable et hémorragique ; mais la cervicite est le plus souvent asymptomatique.","src":"p. 184"},{"id":"d162-qroc-752","type":"QROC","rank":"A","objective":"d162-obj-10","tags":["clinique"],"difficulty":2,"question":"Citez un signe fonctionnel possible d'une cervicite symptomatique à Chlamydia trachomatis.","answer":"Leucorrhées, cystalgies, syndrome urétral ou dyspareunie","accept":["leucorrhées blanchâtres","leucorrhées jaunâtres","cystalgies","syndrome urétral","dyspareunie"],"keywords":["leucorrh","dyspareunie"],"explanation":"Si elle est symptomatique : leucorrhées blanchâtres ou jaunâtres, cystalgies, syndrome urétral et/ou dyspareunie.","src":"p. 184"},{"id":"d162-qroc-753","type":"QROC","rank":"B","objective":"d162-obj-09","tags":["complications"],"difficulty":2,"question":"Quelles sont les complications locorégionales de la chlamydiose chez l'homme ?","answer":"Épididymite aiguë et prostatite chronique","accept":["épididymite aiguë et prostatite chronique","épididymite et prostatite"],"keywords":["epididym","prostat"],"explanation":"Chez l'homme : épididymite aiguë et prostatite chronique (les prostatites aiguës à C. trachomatis sont rares).","src":"p. 184"},{"id":"d162-qroc-754","type":"QROC","rank":"B","objective":"d162-obj-13","tags":["complications"],"difficulty":2,"question":"Sous quel mode évolutif se présentent le plus souvent l'endométrite et la salpingite à C. trachomatis ?","answer":"Subaiguës ou chroniques","accept":["subaiguës ou chroniques","subaiguë","chroniques"],"keywords":["subaigu","chroni"],"explanation":"Les infections hautes à Chlamydia évoluent souvent à bas bruit, de façon subaiguë ou chronique, d'où le risque de séquelles tardives.","src":"p. 184"},{"id":"d162-qroc-755","type":"QROC","rank":"B","objective":"d162-obj-35","tags":["complications","suivi"],"difficulty":2,"question":"Quelles séquelles tardives menacent la femme après une infection génitale haute à Chlamydia ?","answer":"Algies pelviennes inflammatoires, stérilité tubaire, GEU","accept":["algies pelviennes, stérilité tubaire et grossesse extra-utérine","algies pelviennes inflammatoires, stérilité tubaire, geu"],"keywords":["algies","steril","extra"],"explanation":"Secondairement à l'endométrite ou à la salpingite : algies pelviennes inflammatoires, stérilité tubaire et grossesse extra-utérine.","src":"p. 184"},{"id":"d162-qroc-756","type":"QROC","rank":"B","objective":"d162-obj-14","tags":["complications"],"difficulty":3,"question":"Quelle complication hépatique rare de la chlamydiose féminine simule une cholécystite alithiasique ?","answer":"La péri-hépatite (diagnostic sous cœlioscopie)","accept":["péri-hépatite","périhépatite","peri hepatite"],"keywords":["peri","hepat"],"explanation":"Plus rarement, une péri-hépatite donne un tableau de cholécystite alithiasique dont le diagnostic se fait sous cœlioscopie.","src":"p. 184"},{"id":"d162-qroc-757","type":"QROC","rank":"B","objective":"d162-obj-14","tags":["complications"],"difficulty":2,"question":"Quel syndrome associe polyarthrite réactionnelle, urétrite, conjonctivite bilatérale, balanite circinée et kératodermie palmo-plantaire psoriasiforme ?","answer":"Le syndrome oculo-urétro-synovial","accept":["oculo-urétro-synovial","oculo-uréthro-synovial","oculo urethro synovial"],"keywords":["oculo"],"explanation":"Syndrome oculo-urétro-synovial : complication d'une chlamydiose dans les deux sexes (polyarthrite aiguë ou subaiguë réactionnelle, urétrite, conjonctivite bilatérale, atteinte cutanée).","src":"p. 184-185"},{"id":"d162-qroc-758","type":"QROC","rank":"B","objective":"d162-obj-14","tags":["complications"],"difficulty":2,"question":"Quelles atteintes cutanées sont décrites dans le syndrome oculo-urétro-synovial d'origine chlamydienne ?","answer":"Balanite circinée et kératodermie palmo-plantaire psoriasiforme","accept":["balanite circinée","kératodermie palmo-plantaire","kératodermie palmo-plantaire psoriasiforme"],"keywords":["balanite","keratodermie"],"explanation":"Les deux atteintes cutanéo-muqueuses du syndrome sont la balanite circinée et la kératodermie palmo-plantaire psoriasiforme.","src":"p. 185"},{"id":"d162-qroc-759","type":"QROC","rank":"B","objective":"d162-obj-36","tags":["pédiatrie","complications"],"difficulty":2,"question":"Quelles manifestations peut présenter un nouveau-né dont la mère a une infection urogénitale à Chlamydia ?","answer":"Kératoconjonctivite et pneumopathie","accept":["kératoconjonctivite et pneumopathie","conjonctivite et pneumopathie"],"keywords":["conjonctivite","pneumopathie"],"explanation":"Chez le nouveau-né : kératoconjonctivite et pneumopathie ; le traitement repose sur l'érythromycine.","src":"p. 185"},{"id":"d162-qroc-760","type":"QROC","rank":"A","objective":"d162-obj-33","tags":["paraclinique"],"difficulty":1,"question":"Quel examen est l'examen clé du diagnostic d'une infection à C. trachomatis, plus sensible que la culture ?","answer":"La PCR (amplification génique)","accept":["pcr","amplification génique"],"keywords":["pcr"],"explanation":"La PCR est l'examen clé ; la sérologie n'a aucun intérêt.","src":"p. 185"},{"id":"d162-qroc-761","type":"QROC","rank":"A","objective":"d162-obj-18","tags":["traitement"],"difficulty":2,"question":"Quel est l'avantage pratique du traitement de la chlamydiose par azithromycine ?","answer":"Dose unique : traitement immédiat sans crainte de mauvaise observance","accept":["dose unique","prise unique","pas de mauvaise observance","traitement immédiat"],"keywords":["unique"],"explanation":"L'azithromycine est délivrée en dose unique, ce qui permet de traiter immédiatement sans craindre une mauvaise observance ; son inconvénient est l'émergence de résistances (Mycoplasma genitalium).","src":"p. 185"},{"id":"d162-qroc-762","type":"QROC","rank":"B","objective":"d162-obj-34","tags":["traitement"],"difficulty":2,"question":"Quelle est la posologie de la doxycycline en première intention dans une chlamydiose non compliquée ?","answer":"100 mg toutes les 12 h pendant 7 jours","accept":["100 mg matin et soir 7 jours","100 mg x 2 par jour pendant 7 jours","100 mg/12 h 7 jours"],"keywords":["100","7"],"explanation":"Première intention : doxycycline 100 mg/12 h pendant 7 jours per os.","src":"p. 185"},{"id":"d162-qroc-763","type":"QROC","rank":"B","objective":"d162-obj-34","tags":["traitement","pièges"],"difficulty":2,"question":"Quelle dose d'azithromycine en prise unique traite une chlamydiose non compliquée en cas de crainte de mauvaise observance ?","answer":"1 g","accept":["1 g","1g","1000 mg"],"keywords":["1 g"],"explanation":"Chlamydia : azithromycine 1 g en dose unique ; gonocoque (en cas d'allergie aux β-lactamines) : 2 g.","src":"p. 185"},{"id":"d162-qroc-764","type":"QROC","rank":"B","objective":"d162-obj-34","tags":["traitement"],"difficulty":2,"question":"Citez un antibiotique de deuxième intention dans une chlamydiose non compliquée.","answer":"Érythromycine ou ofloxacine, pendant 7 jours","accept":["érythromycine","ofloxacine"],"keywords":["erythromycine","ofloxacine"],"explanation":"Deuxième intention : érythromycine 500 mg/6 h ou ofloxacine 200 mg/12 h, pendant 7 jours.","src":"p. 185"},{"id":"d162-qroc-765","type":"QROC","rank":"B","objective":"d162-obj-16","tags":["suivi","pièges"],"difficulty":3,"question":"Pendant combien de temps après le traitement la PCR de contrôle d'une chlamydiose peut-elle être faussement positive (débris cellulaires) ?","answer":"4 semaines","accept":["4 semaines","un mois","28 jours"],"keywords":["4 semaines"],"explanation":"Des débris cellulaires de Chlamydia persistent jusqu'à 4 semaines : un contrôle PCR trop précoce peut être faussement positif.","src":"p. 185"},{"id":"d162-qroc-766","type":"QROC","rank":"B","objective":"d162-obj-16","tags":["suivi"],"difficulty":2,"question":"Chez quels patients contrôle-t-on les sites atteints 3 à 6 mois après le traitement d'une chlamydiose ?","answer":"Ceux à haut risque de réinfection","accept":["haut risque de réinfection","risque de réinfection","haut risque"],"keywords":["reinfection"],"explanation":"Un contrôle des sites atteints (vaginal, urétral, pharyngé, anal) est préconisé 3 à 6 mois après traitement chez les patients exposés à un haut risque de réinfection.","src":"p. 185"},{"id":"d162-qroc-767","type":"QROC","rank":"B","objective":"d162-obj-34","tags":["traitement","grossesse"],"difficulty":2,"question":"Quel antibiotique traite une chlamydiose chez la femme enceinte, et quel contrôle systématique est prévu ?","answer":"Azithromycine 1 g en prise unique ; PCR à 1 mois","accept":["azithromycine et pcr à 1 mois","azithromycine 1 g pcr 1 mois"],"keywords":["azithromycine","1 mois"],"explanation":"Femme enceinte : azithromycine 1 g en prise orale unique, avec PCR systématique à 1 mois.","src":"p. 186"},{"id":"d162-qroc-768","type":"QROC","rank":"B","objective":"d162-obj-34","tags":["traitement"],"difficulty":2,"question":"Quelle est la durée de la doxycycline (100 mg/12 h) dans une orchiépididymite à C. trachomatis ?","answer":"10 jours","accept":["10 jours","dix jours"],"keywords":["10 jours"],"explanation":"Orchiépididymite à Chlamydia : doxycycline 100 mg/12 h pendant 10 jours (7 jours pour une forme non compliquée, 14 jours pour une endométrite-salpingite).","src":"p. 186"},{"id":"d162-qroc-769","type":"QROC","rank":"B","objective":"d162-obj-21","tags":["traitement"],"difficulty":2,"question":"Quelle est la durée de la doxycycline (PO ou IV) dans une endométrite ou une salpingite à Chlamydia ?","answer":"14 jours","accept":["14 jours","quatorze jours","2 semaines"],"keywords":["14"],"explanation":"Endométrite, salpingite : doxycycline 100 mg/12 h par voie orale ou IV pendant 14 jours.","src":"p. 186"},{"id":"d162-qroc-770","type":"QROC","rank":"B","objective":"d162-obj-34","tags":["traitement","pédiatrie"],"difficulty":2,"question":"Quel antibiotique traite une pneumopathie ou une ophtalmie néonatale à C. trachomatis ?","answer":"L'érythromycine (12,5 mg/kg/6 h, pendant 14 jours)","accept":["érythromycine","erythromycine 12,5 mg/kg"],"keywords":["erythromycine"],"explanation":"Chez le nouveau-né : érythromycine 12,5 mg/kg toutes les 6 h, PO ou IV, pendant 14 jours.","src":"p. 186"},{"id":"d162-qroc-771","type":"QROC","rank":"B","objective":"d162-obj-21","tags":["traitement"],"difficulty":2,"question":"Quelle association antibiotique est préconisée (recommandations 2018) pour une infection génitale haute non compliquée ?","answer":"Ceftriaxone + doxycycline + métronidazole","accept":["ceftriaxone doxycycline métronidazole","ceftriaxone, doxycycline et métronidazole"],"keywords":["ceftriaxone","doxycycline","metronidazole"],"explanation":"Ceftriaxone 1 g IV/IM en dose unique, doxycycline 100 mg/12 h et métronidazole 500 mg/12 h pendant 10 jours.","src":"p. 186"},{"id":"d162-qroc-772","type":"QROC","rank":"B","objective":"d162-obj-21","tags":["traitement","suivi"],"difficulty":2,"question":"Quel contrôle systématique fait-on après le traitement d'une infection génitale haute, et à quel délai ?","answer":"PCR de contrôle 2 à 3 mois après le traitement","accept":["pcr à 2 à 3 mois","pcr 2-3 mois","contrôle pcr à 2 à 3 mois"],"keywords":["pcr","mois"],"explanation":"Un contrôle PCR systématique est à faire 2 à 3 mois après le traitement d'une IGH.","src":"p. 186"},{"id":"d162-qroc-773","type":"QROC","rank":"B","objective":"d162-obj-21","tags":["traitement"],"difficulty":1,"question":"Comment débute habituellement la prise en charge d'une infection génitale haute ?","answer":"Par un traitement probabiliste","accept":["probabiliste","traitement probabiliste","initialement probabiliste"],"keywords":["probabil"],"explanation":"La prise en charge des IGH est souvent initialement probabiliste.","src":"p. 186"},{"id":"d162-qroc-774","type":"QROC","rank":"A","objective":"d162-obj-23","tags":["définition","étiologie"],"difficulty":1,"question":"Quel est l'agent de la syphilis ?","answer":"Treponema pallidum (un spirochète)","accept":["treponema pallidum","tréponème pâle","tréponème","t. pallidum"],"keywords":["treponem"],"explanation":"La syphilis est une IST due à un spirochète, Treponema pallidum ; le tréponème ne se cultive pas in vitro.","src":"p. 187"},{"id":"d162-qroc-775","type":"QROC","rank":"A","objective":"d162-obj-23","tags":["définition","physiopathologie"],"difficulty":2,"question":"Pourquoi une personne guérie d'une syphilis peut-elle se recontaminer ?","answer":"La syphilis est une maladie non immunisante","accept":["non immunisante","pas d'immunité","ne confère pas d'immunité"],"keywords":["immunis"],"explanation":"C'est une maladie non immunisante et très contagieuse ; une recontamination se reconnaît cliniquement ou à la remontée du TNT.","src":"p. 187"},{"id":"d162-qroc-776","type":"QROC","rank":"B","objective":"d162-obj-02","tags":["épidémiologie"],"difficulty":1,"question":"Quel groupe est principalement touché par la recrudescence de la syphilis en métropole depuis 2000 ?","answer":"Les homosexuels masculins","accept":["homosexuels masculins","hsh","homosexuels","hommes ayant des rapports sexuels avec des hommes"],"keywords":["homosex"],"explanation":"La recrudescence touche surtout les homosexuels masculins et traduit un relâchement de la prévention des pratiques à risque.","src":"p. 187"},{"id":"d162-qroc-777","type":"QROC","rank":"B","objective":"d162-obj-02","tags":["épidémiologie"],"difficulty":2,"question":"Quelle proportion de patients syphilitiques est infectée par le VIH (sur-représentation) ?","answer":"Environ 40 %","accept":["40 %","40","environ 40 %"],"keywords":["40"],"explanation":"Les patients infectés par le VIH sont sur-représentés parmi les syphilitiques (40 %).","src":"p. 188"},{"id":"d162-qroc-778","type":"QROC","rank":"B","objective":"d162-obj-02","tags":["épidémiologie"],"difficulty":2,"question":"Dans quels territoires l'atteinte des hétérosexuels fait-elle craindre une réémergence de la syphilis congénitale ?","answer":"Départements et régions d'outre-mer","accept":["outre-mer","dom","dom-tom"],"keywords":["outre"],"explanation":"L'atteinte des hétérosexuels est de plus en plus nette dans les DROM, d'où la crainte d'une réémergence de la syphilis congénitale.","src":"p. 188"},{"id":"d162-qroc-779","type":"QROC","rank":"A","objective":"d162-obj-03","tags":["prévention","suivi"],"difficulty":2,"question":"À quelle fréquence minimale la sérologie de la syphilis est-elle recommandée chez les patients infectés par le VIH engagés dans des pratiques à risque ?","answer":"Au moins 1 fois par an","accept":["1 fois par an","une fois par an","tous les ans","annuelle"],"keywords":["par an"],"explanation":"Sérologie systématique chez les sujets à risque à partenaires multiples, et au moins une fois par an chez les patients VIH.","src":"p. 199"},{"id":"d162-qroc-780","type":"QROC","rank":"B","objective":"d162-obj-03","tags":["prévention","grossesse"],"difficulty":1,"question":"À quel moment de la grossesse la sérologie de la syphilis est-elle obligatoire ?","answer":"Au 1er trimestre","accept":["1er trimestre","premier trimestre","au premier trimestre"],"keywords":["trimestre"],"explanation":"La sérologie syphilis est obligatoire au 1er trimestre de la grossesse et peut être renouvelée dans certaines situations.","src":"p. 188"},{"id":"d162-qroc-781","type":"QROC","rank":"B","objective":"d162-obj-23","tags":["clinique","prévention"],"difficulty":2,"question":"Quelles lésions de la syphilis sont contagieuses ?","answer":"Lésions des muqueuses (et syphilides si grattées ou excoriées)","accept":["lésions muqueuses","lésions des muqueuses","muqueuses","syphilides excoriées"],"keywords":["muqueu"],"explanation":"Transmission essentiellement sexuelle (fellation comprise) ; sont contagieuses les lésions muqueuses et les syphilides en cas de grattage ou d'excoriation.","src":"p. 188"},{"id":"d162-qroc-782","type":"QROC","rank":"A","objective":"d162-obj-23","tags":["définition"],"difficulty":1,"question":"Quelles formes cliniques composent la syphilis précoce ?","answer":"Primaire, secondaire et latente précoce","accept":["primaire, secondaire et latente précoce","primaire secondaire latente précoce"],"keywords":["primaire","secondaire","latente"],"explanation":"La syphilis précoce regroupe la syphilis primaire, la syphilis secondaire et la syphilis latente précoce.","src":"p. 188"},{"id":"d162-qroc-783","type":"QROC","rank":"A","objective":"d162-obj-24","tags":["définition"],"difficulty":1,"question":"Quelles formes composent la syphilis tardive ?","answer":"Syphilis tertiaire et syphilis latente tardive","accept":["tertiaire et latente tardive","tertiaire latente tardive"],"keywords":["tertiaire","latente"],"explanation":"La syphilis tardive regroupe la syphilis tertiaire et la syphilis latente tardive (non datable ou datant de plus de 1 an).","src":"p. 188"},{"id":"d162-qroc-784","type":"QROC","rank":"A","objective":"d162-obj-23","tags":["définition"],"difficulty":1,"question":"Quelle durée d'évolution sépare la syphilis latente précoce de la syphilis latente tardive ?","answer":"1 an","accept":["1 an","un an","12 mois"],"keywords":["1 an"],"explanation":"Latente précoce : sérologie positive sans lésion clinique, évolution de moins de 1 an ; latente tardive : non datable ou de plus de 1 an.","src":"p. 188"},{"id":"d162-qroc-785","type":"QROC","rank":"A","objective":"d162-obj-23","tags":["clinique"],"difficulty":1,"question":"Quelle est la durée d'incubation moyenne de la syphilis primaire ?","answer":"3 semaines","accept":["3 semaines","trois semaines","21 jours"],"keywords":["3 semaines"],"explanation":"L'incubation est de 10 à 90 jours, en moyenne 3 semaines.","src":"p. 188"},{"id":"d162-qroc-786","type":"QROC","rank":"A","objective":"d162-obj-23","tags":["clinique"],"difficulty":2,"question":"Quelles sont les limites (minimum et maximum) de l'incubation de la syphilis primaire ?","answer":"10 à 90 jours","accept":["10 à 90 jours","10-90 jours","10 à 90"],"keywords":["10","90"],"explanation":"Incubation variable : 10 à 90 jours, en moyenne 3 semaines.","src":"p. 188"},{"id":"d162-qroc-787","type":"QROC","rank":"A","objective":"d162-obj-07","tags":["clinique","physiopathologie"],"difficulty":1,"question":"Pourquoi le chancre syphilitique est-il contagieux ?","answer":"Il fourmille de tréponèmes","accept":["fourmille de tréponèmes","riche en tréponèmes","nombreux tréponèmes"],"keywords":["treponem"],"explanation":"Le chancre est très riche en tréponèmes : il est contagieux, y compris quand il n'est pas visible.","src":"p. 188"},{"id":"d162-qroc-788","type":"QROC","rank":"A","objective":"d162-obj-07","tags":["clinique","pièges"],"difficulty":2,"question":"Citez une localisation du chancre syphilitique qui fait souvent méconnaître la syphilis primaire (chancre non visible).","answer":"Vaginal, du col utérin, anorectal ou pharyngé","accept":["chancre vaginal","col utérin","anorectal","pharyngé"],"keywords":["vagin","col","anorect"],"explanation":"Quand le chancre n'est pas visible (vagin, col utérin, anorectal, pharynx), le diagnostic de syphilis primaire est souvent méconnu.","src":"p. 188"},{"id":"d162-qroc-789","type":"QROC","rank":"A","objective":"d162-obj-07","tags":["clinique"],"difficulty":2,"question":"Quelle lésion élémentaire correspond typiquement à un chancre syphilitique (perte de substance superficielle) ?","answer":"Une exulcération (érosion)","accept":["exulcération","érosion","exulceration"],"keywords":["exulc","erosion"],"explanation":"Le chancre est typiquement une exulcération, plus rarement une ulcération muqueuse (perte de substance profonde).","src":"p. 188"},{"id":"d162-qroc-790","type":"QROC","rank":"A","objective":"d162-obj-07","tags":["clinique"],"difficulty":2,"question":"Quel est le diamètre moyen d'un chancre syphilitique ?","answer":"5 à 15 mm","accept":["5 à 15 mm","5-15 mm","5 à 15"],"keywords":["5","15"],"explanation":"Le chancre mesure en moyenne 5 à 15 mm, est unique (parfois multiple, en miroir), à fond propre et rosé, induré, indolore.","src":"p. 188"},{"id":"d162-qroc-791","type":"QROC","rank":"A","objective":"d162-obj-07","tags":["clinique"],"difficulty":2,"question":"Comment décrit-on le fond d'un chancre syphilitique ?","answer":"Propre et rosé","accept":["propre et rosé","fond propre","propre"],"keywords":["propre"],"explanation":"Fond propre et rosé, à la différence du chancre mou (fond sale).","src":"p. 188"},{"id":"d162-qroc-792","type":"QROC","rank":"A","objective":"d162-obj-07","tags":["clinique"],"difficulty":2,"question":"Comment met-on en évidence l'induration d'un chancre syphilitique ?","answer":"Impossibilité de plisser la lésion entre deux doigts","accept":["plisser entre deux doigts","impossible de plisser","pincer entre deux doigts"],"keywords":["doigts"],"explanation":"La surface de l'ulcération ne peut pas être plissée entre deux doigts : elle fait bloc avec l'induration sous-jacente (seul caractère vraiment évocateur).","src":"p. 188"},{"id":"d162-qroc-793","type":"QROC","rank":"A","objective":"d162-obj-07","tags":["clinique"],"difficulty":2,"question":"Quel aspect particulier peuvent présenter des chancres syphilitiques multiples ?","answer":"Des images en miroir","accept":["images en miroir","en miroir","miroir"],"keywords":["miroir"],"explanation":"Le chancre est unique en général, mais peut être multiple avec des images en miroir.","src":"p. 188"},{"id":"d162-qroc-794","type":"QROC","rank":"A","objective":"d162-obj-07","tags":["clinique"],"difficulty":1,"question":"Quel est le siège électif du chancre syphilitique chez l'homme ?","answer":"Le sillon balano-préputial","accept":["sillon balano-préputial","sillon balanopréputial","sillon"],"keywords":["sillon"],"explanation":"Chez l'homme, le chancre siège assez électivement dans le sillon balano-préputial, plus rarement sur le gland ou le fourreau.","src":"p. 189"},{"id":"d162-qroc-795","type":"QROC","rank":"A","objective":"d162-obj-07","tags":["clinique"],"difficulty":2,"question":"Où siège le plus souvent le chancre syphilitique chez la femme ?","answer":"Sur la vulve (petites lèvres, grandes lèvres, fourchette)","accept":["vulve","partie externe de la vulve","petites lèvres"],"keywords":["vulv"],"explanation":"Chez la femme, le chancre est le plus souvent vulvaire ; plus rarement vaginal, il passe alors volontiers inaperçu.","src":"p. 189"},{"id":"d162-qroc-796","type":"QROC","rank":"A","objective":"d162-obj-07","tags":["clinique"],"difficulty":2,"question":"Quelles localisations muqueuses extragénitales peut avoir un chancre syphilitique, dans les deux sexes ?","answer":"Buccale ou pharyngée (fellation) et anorectale","accept":["buccale","pharyngée","anorectale","bouche"],"keywords":["bucc","anorect"],"explanation":"Dans les deux sexes, le chancre peut siéger sur la muqueuse buccale ou pharyngée (fellation) ou anorectale.","src":"p. 189"},{"id":"d162-qroc-797","type":"QROC","rank":"A","objective":"d162-obj-07","tags":["clinique"],"difficulty":3,"question":"Quelle particularité de l'adénopathie satellite existe quand le chancre siège sur le col utérin ou le rectum ?","answer":"Elle n'est pas visible cliniquement","accept":["non visible","pas visible","non palpable","invisible"],"keywords":["non visible"],"explanation":"Pour les chancres du col utérin et du rectum, l'adénopathie satellite n'est pas visible cliniquement.","src":"p. 190"},{"id":"d162-qroc-798","type":"QROC","rank":"A","objective":"d162-obj-07","tags":["clinique","physiopathologie"],"difficulty":1,"question":"Quelle est l'évolution spontanée d'un chancre syphilitique non traité ?","answer":"Régression spontanée sans séquelle en quelques semaines","accept":["régression spontanée","guérison spontanée","disparaît spontanément"],"keywords":["spontan"],"explanation":"Le chancre régresse sans séquelle en quelques semaines (rarement plusieurs mois) : le patient paraît guéri mais la maladie peut évoluer vers les stades suivants.","src":"p. 190"},{"id":"d162-qroc-799","type":"QROC","rank":"A","objective":"d162-obj-23","tags":["clinique","épidémiologie"],"difficulty":2,"question":"Quelle proportion des patients ayant eu un chancre visible, non traités, présentera une syphilis secondaire ?","answer":"Environ 30 %","accept":["30 %","30","environ 30 %"],"keywords":["30"],"explanation":"Environ 30 % des chancres visibles non traités évoluent vers la syphilis secondaire ; une syphilis tardive peut aussi apparaître sans passer par des signes secondaires.","src":"p. 190"}],"edn":[],"trees":[],"treatments":{"data":[],"strategies":[]},"cases":[],"ecg":{"data":[],"method":""},"echo":{"data":[]},"flash":null,"pareto":{"id":"d162-pareto","points":[{"id":"d162-par-01","rank":"A","cat":"clinique","text":"Chancre syphilitique = ulcération **indolore**, à fond propre, **indurée** + adénopathie satellite **non inflammatoire** ; évoquer la syphilis devant toute ulcération muqueuse aiguë (génitale, orale, anale)","src":"p. 188-190"},{"id":"d162-par-02","rank":"A","cat":"examen","text":"Sérologie syphilis : **ELISA (TT) en 1er** ; **TNT** (VDRL/RPR) seulement si TT positif ; syphilis secondaire = **TT + TNT toujours positifs**","src":"p. 194-195, 200"},{"id":"d162-par-03","rank":"A","cat":"piège","text":"**7 premiers jours du chancre** : TT et TNT possiblement **négatifs** → devant une ulcération génitale, **ne pas attendre** la sérologie pour traiter (OMS)","src":"p. 194-197"},{"id":"d162-par-04","rank":"A","cat":"traitement","text":"Syphilis précoce (primaire, secondaire, latente précoce) : **benzathine-benzylpénicilline 2,4 MU IM en 1 injection** ; si allergie : **doxycycline 14 j** (sauf grossesse et VIH)","src":"p. 197-198"},{"id":"d162-par-05","rank":"A","cat":"suivi","text":"Suivi syphilis : **TNT quantitatif** ; titre **divisé par 4 à 6 mois** ; contrôles à 3 mois, 6 mois, 1 an puis annuels ; titre multiplié par 4 = recontamination","src":"p. 195, 198"},{"id":"d162-par-06","rank":"A","cat":"piège","text":"**Herxheimer** (fièvre, céphalées, myalgies quelques heures après l'injection) = lyse des tréponèmes, bénigne ; ce n'est **pas une allergie** à la pénicilline","src":"p. 198"},{"id":"d162-par-07","rank":"A","cat":"piège","text":"TNT positif isolé (TT négatif) = **fausse sérologie** (**lupus**, SAPL, grossesse) ; TT positif + TNT négatif = cicatrice sérologique","src":"p. 194-196"},{"id":"d162-par-08","rank":"A","cat":"clinique","text":"Syphilis secondaire = « grande simulatrice » : papules **cuivrées**, papules **palmo-plantaires** très évocatrices ; roséole à ne pas confondre avec virose ou toxidermie","src":"p. 191-192, 200"},{"id":"d162-par-09","rank":"A","cat":"traitement","text":"Urétrite : traitement minute **ceftriaxone** (gonocoque) + **anti-Chlamydia systématique** (**doxycycline 7 j** préférée à l'azithromycine 1 g) ; traiter les partenaires ; rapports protégés ≥ 7 j","src":"p. 182, 187"},{"id":"d162-par-10","rank":"A","cat":"clinique","text":"Gonococcie : incubation **2-7 j**, écoulement **purulent** (90 %), femme **asymptomatique 70 %** ; diagnostic par **PCR** (1er jet urinaire chez l'homme, auto-écouvillonnage vaginal chez la femme)","src":"p. 180-181"},{"id":"d162-par-11","rank":"A","cat":"piège","text":"Chlamydia : **portage asymptomatique** fréquent (50 % H, 50-90 % F), écoulement clair intermittent ; examen clé = **PCR** ; la **sérologie est inutile**","src":"p. 184-185"},{"id":"d162-par-12","rank":"A","cat":"prévention","text":"Devant toute IST : dépister/traiter les **partenaires** ; proposer **VIH + test tréponémique + hépatite B** ; pas de rapports non protégés pendant le traitement ; **PrEP** si risques répétés","src":"p. 182, 185, 208"},{"id":"d162-par-13","rank":"A","cat":"examen","text":"Condylomes : diagnostic **clinique** (crêtes-de-coq) ; chercher une **IST associée** (25 %) ; col : frottis **tous les 3 ans** ou **test HPV-HR dès 30 ans**","src":"p. 201-202, 205"},{"id":"d162-par-14","rank":"A","cat":"prévention","text":"Vaccin anti-HPV **nonavalent** : filles et garçons **11-14 ans** (2 doses), rattrapage **15-19 ans** (3 doses 0-2-6 mois), HSH jusqu'à **26 ans**","src":"p. 204-205"},{"id":"d162-par-15","rank":"A","cat":"prévention","text":"Contact d'une syphilis certaine : **< 6 semaines → traiter d'emblée** (2,4 MU) ; **> 6 semaines → sérologie**, refaite à 3 mois si négative","src":"p. 198"}]},"extra":{"semio":[],"criteres":[],"chiffres":[],"physio":[],"parcours":[],"examens":[]}});
